INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C1','kor',1,2,'u2',3,'글자의 짜임과 받침 — 첫소리·가운뎃소리·받침으로 된 글자의 짜임, 쌍받침(같은 자음자가 겹침)과 겹받침(서로 다른 자음자 두 개) 구별, 공통 받침 채우기',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C2','kor',1,2,'u2',5,'받침에 주의하며 문장 쓰기 — 소리 나는 대로가 아니라 낱말대로 쓰기(밝다·넓다·앓다·없다), 잘못 쓴 글자 고쳐 쓰기(닥→닭·짭다→짧다)',ARRAY['2국03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C3','kor',1,2,'u2',7,'받침이 있는 낱말 바르게 읽기 — 겹받침은 뒤에 자음이 오거나 끝나면 하나만 소리 남(흙 속에[흑쏘게]), 모음이 오면 넘어가 소리 남(흙이[흘기]), ㅟ 바르게 읽기, 낱말 뜻 알기',ARRAY['2국02-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C4','kor',1,2,'u2',9,'글쓴이가 하고 싶은 말 찾기 — 글쓴이가 누구인지·글의 제목·글을 쓴 까닭을 살펴 하고 싶은 말 찾기, 글쓴이의 생각은 제목에 나타나기도 함',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C5','kor',1,2,'u2',11,'인물의 생각 알기 — 인물이 한 말이나 행동으로 생각 알기, 같은 물음에 사람마다 생각이 다를 수 있음(「다니엘의 멋진 날」)',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C6','kor',1,2,'u2',13,'주변에서 겹받침 낱말 찾기 — 책·교실 둘레에서 겹받침 낱말 찾기, 홑받침·쌍받침·겹받침 구별, 낱말 카드에 바르게 쓰기',ARRAY['2국04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X01','kor',1,'u2',ARRAY['K1-2-u2-C1','K1-2-u2-C6']::text[],'쌍받침과 겹받침을 뒤바꾼다 (낚의 ㄲ을 겹받침으로, 밟의 ㄼ을 쌍받침으로)','「같은 자음자가 겹쳤나, 서로 다른 자음자 둘인가」 받침만 따로 써 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X02','kor',1,'u2',ARRAY['K1-2-u2-C1','K1-2-u2-C6']::text[],'받침이 하나이거나 없는 글자를 겹받침 글자로 고른다 (어·운·즐·강)','글자를 첫소리·가운뎃소리·받침으로 나눠 쓰고 받침 자리에 자음자가 몇 개인지 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X03','kor',1,'u2',ARRAY['K1-2-u2-C1']::text[],'글자의 짜임을 모른다 — 첫소리 자리의 ㄲ·ㅆ을 받침으로 보거나, 겹받침 가운데 하나만 받침으로 여긴다 (끓의 받침을 ㄹ만으로)','「끓」을 ㄲ·ㅡ·ㅀ 세 조각으로 떼어 자리 이름을 붙여 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X04','kor',1,'u2',ARRAY['K1-2-u2-C2','K1-2-u2-C6']::text[],'소리 나는 대로 쓴다 (닭→닥, 짧다→짭다, 닳았다→달았다, 여덟→여덜)','「소리는 하나만 나도 쓸 때는 낱말대로」 — 뜻을 먼저 떠올리고 받침을 정하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X05','kor',1,'u2',ARRAY['K1-2-u2-C1','K1-2-u2-C2']::text[],'겹받침의 짝을 틀리게 쓴다 (닳았다→닭았다, 넓다→넒다, 맑의 받침을 ㄼ으로)','그 낱말이 들어간 문장을 뜻으로 읽고 바른 받침 짝을 눈으로 확인하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X06','kor',1,'u2',ARRAY['K1-2-u2-C2']::text[],'소리가 같거나 비슷한 다른 낱말과 헷갈린다 (없다/업다, 앓다/알다, 읽었다/익었다, 않아/안아)','두 낱말을 나란히 놓고 「뜻이 무엇인지」 그림이나 몸으로 견주게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X07','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'뒤에 자음이 오거나 낱말이 끝날 때 겹받침을 둘 다 소리 내거나 엉뚱한 쪽을 소리 낸다 (흙 속에→[흘쏘게])','「뒤에 무엇이 오나요?」 자음이면 하나만 소리 난다는 것을 흙이·흙 속에로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X08','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'뒤에 모음이 와도 받침 하나만 소리 내거나 글자대로 끊어 읽는다 (흙이→[흐기]·[흑이])','뒤 글자에 모음이 오면 받침 하나가 넘어가는 것을 손으로 밀어 보이며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X09','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'ㅟ를 ㅣ로 읽는다 (까마귀→[까마기], 다람쥐→[다람지])','입술을 동그랗게 모았다가 펴며 소리 내는지 거울로 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X10','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글의 첫 문장만 보고 하고 싶은 말을 정한다','「끝까지 읽고 제목과 쓴 까닭을 이으면 어떻게 되나요?」 다시 읽게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X11','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글 속의 한 가지 일이나 세부 내용을 하고 싶은 말로 고른다 (동생은 물건을 아무 데나 둔다)','「그 문장은 글쓴이가 우리에게 하라는 말인가요, 있었던 일인가요?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X12','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글쓴이가 누구인지 모른다 — 글에 나오는 사람이나 편지를 받는 사람을 글쓴이로 여긴다 (동생·준호)','글의 처음이나 끝에서 이름을 찾아 「이 사람이 이 글을 썼다」고 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X13','kor',1,'u2',ARRAY['K1-2-u2-C5']::text[],'인물의 생각을 인물의 말·행동이 아니라 내 생각이나 다른 인물의 말로 짐작한다','「그 인물이 무엇이라고 말했나요?」 말을 다시 읽고 답 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X14','kor',1,'u2',ARRAY['K1-2-u2-C5']::text[],'물음이 하나면 답도 하나뿐이라고 여겨 다른 생각을 틀렸다고 한다','나와 다른 답에 「왜 그렇게 생각했는지」 까닭을 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X15','kor',1,'u2',ARRAY['K1-2-u2-C6']::text[],'낱말 카드·찾기 놀이의 목적을 그림 그리기나 이기기로 여긴다 (그림에만 힘쓰고 낱말을 소리대로 쓴다)','「카드에서 제일 중요한 것이 무엇인가요?」 낱말을 바르게 썼는지부터 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X16','kor',1,'u2',ARRAY['K1-2-u2-C3','K1-2-u2-C5']::text[],'낱말의 뜻을 겉소리로 짐작한다 (간신히·하마터면·귀가·요원·건널목)','그 낱말이 나온 앞뒤 줄을 다시 읽고 무슨 뜻인지 장면으로 바꿔 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#1','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','『국어』 35쪽 생각 열기 — 게시판이 붙어 있는 그림 속 장소는 어디인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":1,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 35쪽 생각 열기 — 게시판이 붙어 있는 그림 속 장소는 어디인가요?","options":[{"t":"박물관","correct":true},{"t":"수영장","mis":"K1-2-u2-X11"},{"t":"놀이터","mis":"K1-2-u2-X11"}],"explanation":["전시된 물건이 있고 관람할 때 주의할 점이 쓰여 있으니 박물관이에요.","수영장이나 놀이터에는 전시된 물건이 없어요.","게시판 셋째 줄을 다시 읽어 봐요."],"asset":{"type":"scene","icon":"🏛️📋","text":"박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#2','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','『국어』 35쪽 — 게시판의 글을 쓴 사람이 읽는 사람에게 하고 싶은 말은?',ARRAY['K1-2-u2-X10','K1-2-u2-X11']::text[],false,'{"seq":2,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 35쪽 — 게시판의 글을 쓴 사람이 읽는 사람에게 하고 싶은 말은?","options":[{"t":"박물관을 관람할 때 지킬 일을 알려 주고 싶어요","correct":true},{"t":"박물관에 사진을 많이 찍으러 오라고 해요","mis":"K1-2-u2-X10"},{"t":"전시된 물건을 사 가라고 해요","mis":"K1-2-u2-X11"}],"explanation":["사진을 찍지 않고, 떠들지 않고, 물건을 만지지 않기를 바라요.","사진을 찍으라거나 물건을 사라는 말은 없어요.","세 문장이 모두 「~하지 않습니다」예요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#3','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','『국어』 36쪽 — 글에서 받침에 서로 다른 자음자 두 개가 있는 글자는?',ARRAY['K1-2-u2-X03','K1-2-u2-X02']::text[],false,'{"seq":3,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 36쪽 — 글에서 받침에 서로 다른 자음자 두 개가 있는 글자는?","options":[{"t":"붉","correct":true},{"t":"썩","mis":"K1-2-u2-X03"},{"t":"밭","mis":"K1-2-u2-X02"}],"explanation":["「붉」의 받침에는 ㄹ과 ㄱ, 서로 다른 자음자 두 개가 있어요.","「썩」의 받침은 ㄱ 하나, 「밭」의 받침은 ㅌ 하나예요. 「썩」의 ㅆ은 첫소리예요.","받침 자리를 잘 봐요."],"asset":{"type":"passage","lines":["호랑이가 잡은 동아줄은 썩은 동아줄이었어요.","“어흥! 어흥!”","호랑이는 수수밭으로 뚝 떨어졌어요.","호랑이가 흘린 피 때문에 수수가 붉게 물들었어요."],"title":"국어 36쪽 — 해와 달이 된 오누이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#4','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','『국어』 37쪽 3번 — 글을 읽을 때 받침에 주의하며 읽어야 하는 까닭은?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 37쪽 3번 — 글을 읽을 때 받침에 주의하며 읽어야 하는 까닭은?","options":[{"t":"바르게 읽어야 듣는 사람이 낱말을 정확하게 알 수 있어서","correct":true},{"t":"빨리 읽을 수 있어서","mis":"K1-2-u2-X07"},{"t":"글씨가 예뻐져서","mis":"K1-2-u2-X07"}],"explanation":["받침을 바르게 읽어야 하고 싶은 말을 정확하고 분명하게 전할 수 있어요.","빨리 읽거나 글씨와는 상관없어요.","듣는 사람을 생각해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#5','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','『국어』 35쪽 — 게시판의 세 문장은 어떤 점이 같나요?',ARRAY['K1-2-u2-X11','K1-2-u2-X10']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 35쪽 — 게시판의 세 문장은 어떤 점이 같나요?","options":[{"t":"모두 박물관에서 하지 말아야 할 일을 알려 줘요","correct":true},{"t":"모두 박물관에 있는 물건 이름이에요","mis":"K1-2-u2-X11"},{"t":"첫 문장만 중요한 말이에요","mis":"K1-2-u2-X10"}],"explanation":["세 문장이 모두 「~하지 않습니다」로 끝나요.","물건 이름을 늘어놓은 글이 아니에요. 세 문장을 모두 읽어야 해요.","문장의 끝을 견주어 봐요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#6','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C1',2,'mc','auto','『국어』 37쪽 2번 — 「‘붉게’를 어떻게 읽지?」 두 친구가 궁금해하는 것은?',ARRAY['K1-2-u2-X02','K1-2-u2-X11']::text[],false,'{"seq":6,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어』 37쪽 2번 — 「‘붉게’를 어떻게 읽지?」 두 친구가 궁금해하는 것은?","options":[{"t":"받침에 서로 다른 자음자 두 개가 있는 글자를 읽는 방법","correct":true},{"t":"받침이 없는 글자를 읽는 방법","mis":"K1-2-u2-X02"},{"t":"호랑이가 떨어진 곳","mis":"K1-2-u2-X11"}],"explanation":["「서로 다른 두 개의 자음자로 이루어진 받침은 어떻게 읽어야 할까?」 하고 궁금해해요.","「붉」에는 받침이 있어요. 호랑이 이야기는 궁금한 것이 아니에요.","이 단원에서 배울 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#7','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C1',2,'match','auto','『국어』 36쪽 글의 글자와 받침을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"『국어』 36쪽 글의 글자와 받침을 이어 보세요.","pairs":[{"l":"썩","r":"받침 ㄱ 하나"},{"l":"붉","r":"받침 ㄹ과 ㄱ 두 개"},{"l":"밭","r":"받침 ㅌ 하나"}],"mis":"K1-2-u2-X03","explanation":["「썩」의 ㅆ은 첫소리라 받침이 아니에요.","「붉」만 받침 자리에 자음자가 두 개예요.","글자의 아래쪽 받침 자리만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#8','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C3',2,'ox','auto','받침을 바르게 읽어야 내가 하고 싶은 말을 정확하게 전할 수 있어요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":2,"kind":"ox","stem":"받침을 바르게 읽어야 내가 하고 싶은 말을 정확하게 전할 수 있어요.","answer":"O","reason_options":[{"t":"듣는 사람이 낱말을 정확하게 알아들을 수 있으니까","correct":true},{"t":"받침은 아무렇게나 읽어도 뜻이 같으니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["받침을 잘못 읽으면 다른 낱말로 들릴 수 있어요.","그래서 받침에 주의하며 읽어요.","『국어』 37쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#9','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','둘레에서 받침에 자음자가 두 개인 글자를 찾았어요. 알맞은 것은?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"둘레에서 받침에 자음자가 두 개인 글자를 찾았어요. 알맞은 것은?","options":[{"t":"흙","correct":true},{"t":"강","mis":"K1-2-u2-X02"},{"t":"책","mis":"K1-2-u2-X02"}],"explanation":["「흙」의 받침은 ㄹ과 ㄱ 두 개예요.","「강」은 받침 ㅇ 하나, 「책」은 받침 ㄱ 하나예요.","받침 자리의 자음자 수를 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#10','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C4',3,'mc','auto','『국어』 35쪽 — 이 게시판의 글은 누가 읽으라고 쓴 글일까요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 35쪽 — 이 게시판의 글은 누가 읽으라고 쓴 글일까요?","options":[{"t":"박물관을 관람하러 온 사람들","correct":true},{"t":"전시된 물건들","mis":"K1-2-u2-X12"},{"t":"게시판을 만든 사람 혼자","mis":"K1-2-u2-X12"}],"explanation":["관람할 때 지킬 일이니 관람하러 온 사람들이 읽어요.","물건은 글을 읽지 못하고, 만든 사람 혼자 보려고 붙인 것이 아니에요.","글을 쓴 사람과 읽는 사람을 나누어 생각해요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#1','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',2,'mc','auto','『국어』 36쪽 — 「붉」의 받침에 있는 자음자는?',ARRAY['K1-2-u2-X03','K1-2-u2-X05']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어』 36쪽 — 「붉」의 받침에 있는 자음자는?","options":[{"t":"ㄹ과 ㄱ","correct":true},{"t":"ㄹ 하나","mis":"K1-2-u2-X03"},{"t":"ㅂ과 ㄱ","mis":"K1-2-u2-X05"}],"explanation":["「붉」은 ㅂ·ㅜ·ㄺ으로 짜여 있고, 받침 ㄺ에는 ㄹ과 ㄱ이 있어요.","ㅂ은 첫소리예요. 받침이 ㄹ 하나뿐인 글자는 「불」이에요.","받침 자리만 떼어 봐요."],"asset":{"type":"passage","lines":["호랑이가 잡은 동아줄은 썩은 동아줄이었어요.","“어흥! 어흥!”","호랑이는 수수밭으로 뚝 떨어졌어요.","호랑이가 흘린 피 때문에 수수가 붉게 물들었어요."],"title":"국어 36쪽 — 해와 달이 된 오누이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#2','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C3',2,'mc','auto','「수수가 붉게 물들었어요.」에서 「붉게」의 뜻은?',ARRAY['K1-2-u2-X16']::text[],false,'{"seq":2,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「수수가 붉게 물들었어요.」에서 「붉게」의 뜻은?","options":[{"t":"빨갛게","correct":true},{"t":"하얗게","mis":"K1-2-u2-X16"},{"t":"넓게","mis":"K1-2-u2-X16"}],"explanation":["호랑이가 흘린 피 때문에 수수가 빨갛게 물들었어요.","하얗게나 넓게가 아니에요.","앞 줄을 다시 읽어 봐요."],"asset":{"type":"passage","lines":["호랑이가 잡은 동아줄은 썩은 동아줄이었어요.","“어흥! 어흥!”","호랑이는 수수밭으로 뚝 떨어졌어요.","호랑이가 흘린 피 때문에 수수가 붉게 물들었어요."],"title":"국어 36쪽 — 해와 달이 된 오누이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#3','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',3,'error','auto','받침에 서로 다른 자음자 두 개가 있는 글자를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#4','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C4',3,'mc','auto','게시판의 글을 박물관에 붙여 둔 까닭은 무엇일까요?',ARRAY['K1-2-u2-X11','K1-2-u2-X10']::text[],false,'{"seq":4,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"게시판의 글을 박물관에 붙여 둔 까닭은 무엇일까요?","options":[{"t":"관람하는 사람들이 지킬 일을 알게 하려고","correct":true},{"t":"박물관을 예쁘게 꾸미려고","mis":"K1-2-u2-X11"},{"t":"사진 찍는 곳을 알려 주려고","mis":"K1-2-u2-X10"}],"explanation":["글쓴이는 읽는 사람이 지킬 일을 알기를 바라요.","꾸미거나 사진 찍는 곳을 알리는 글이 아니에요.","글쓴이가 하고 싶은 말과 이어 봐요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#5','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C4',3,'error','auto','친구가 「게시판에서 하고 싶은 말은 ‘사진을 찍지 않습니다’ 하나뿐이에요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X10','K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"친구가 「게시판에서 하고 싶은 말은 ‘사진을 찍지 않습니다’ 하나뿐이에요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"첫 문장만 보았어요 — 세 문장을 모두 읽으면 관람할 때 지킬 일을 알려 줘요","correct":true,"mis_target":"K1-2-u2-X10"},{"t":"맞게 말했어요 — 첫 문장이 제일 중요해요","mis":"K1-2-u2-X10"},{"t":"게시판에는 하고 싶은 말이 없어요","mis":"K1-2-u2-X12"}],"explanation":["세 문장이 모두 지킬 일을 알려 줘요.","첫 문장 하나만으로는 하고 싶은 말을 다 알 수 없어요.","끝까지 읽어요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#6','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C3',3,'mc','auto','받침을 잘못 읽으면 어떤 일이 생길 수 있나요?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":6,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"받침을 잘못 읽으면 어떤 일이 생길 수 있나요?","options":[{"t":"듣는 사람이 다른 낱말로 알아들을 수 있어요","correct":true},{"t":"아무 일도 생기지 않아요","mis":"K1-2-u2-X07"},{"t":"글씨가 저절로 틀려져요","mis":"K1-2-u2-X07"}],"explanation":["받침이 달라지면 다른 낱말이 될 수 있어요.","그래서 받침에 주의하며 읽어야 해요.","『국어』 37쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#7','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',3,'match','auto','글자와 받침의 자음자 수를 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u2-C1","difficulty":3,"kind":"match","stem":"글자와 받침의 자음자 수를 이어 보세요.","pairs":[{"l":"어","r":"받침 없음"},{"l":"강","r":"받침 자음자 한 개"},{"l":"흙","r":"받침 자음자 두 개"}],"mis":"K1-2-u2-X02","explanation":["「어」는 받침이 없고 「강」은 ㅇ 하나예요.","「흙」은 ㄹ과 ㄱ 두 개예요.","받침 자리의 자음자를 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#8','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',4,'sa','auto','『국어』 36쪽 글에서 받침에 서로 다른 자음자 두 개가 있는 글자를 찾아 한 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C1","difficulty":4,"kind":"sa","stem":"『국어』 36쪽 글에서 받침에 서로 다른 자음자 두 개가 있는 글자를 찾아 한 글자로 쓰세요.","answer":["붉","붉게"],"explanation":["「붉게」의 「붉」이에요.","썩·밭·흘은 받침 자음자가 하나예요.","받침 자리를 봐요."],"asset":{"type":"passage","lines":["호랑이가 잡은 동아줄은 썩은 동아줄이었어요.","“어흥! 어흥!”","호랑이는 수수밭으로 뚝 떨어졌어요.","호랑이가 흘린 피 때문에 수수가 붉게 물들었어요."],"title":"국어 36쪽 — 해와 달이 된 오누이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#9','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','『국어』 35쪽 — 게시판의 글쓴이가 하고 싶은 말을 「~하자」로 한 문장 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어』 35쪽 — 게시판의 글쓴이가 하고 싶은 말을 「~하자」로 한 문장 쓰세요.","answer_guide":{"answer":"예: 박물관에서는 사진을 찍지 말고, 떠들지 말고, 물건을 만지지 말자. — 관람할 때 지킬 일이 들어 있으면 맞아요.","scoring_points":["관람할 때 지킬 일이 들어 있는가","세 문장의 뜻을 아울렀는가","「~하자」로 썼는가"]},"explanation":["세 문장을 모아 하고 싶은 말로 바꿔 써요.","한 문장만 옮기면 하고 싶은 말을 다 담지 못해요.","「~하지 않습니다」를 「~하지 말자」로 바꿔 봐요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#10','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C3',4,'essay','teacher','글을 읽을 때 받침에 주의하며 읽어야 하는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C3","difficulty":4,"kind":"essay","stem":"글을 읽을 때 받침에 주의하며 읽어야 하는 까닭을 써 보세요.","answer_guide":{"answer":"예: 받침을 바르게 읽어야 듣는 사람이 낱말을 정확하게 알아들을 수 있기 때문이에요.","scoring_points":["듣는 사람을 생각했는가","정확하게 전한다는 내용이 있는가","문장이 자연스러운가"]},"explanation":["바르게 읽어야 뜻이 정확하게 전해져요.","빨리 읽는 것과는 상관없어요.","『국어』 37쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#1','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','『국어』 38쪽 — 받침에 자음자가 두 개인 글자는?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 38쪽 — 받침에 자음자가 두 개인 글자는?","options":[{"t":"밟","correct":true},{"t":"어","mis":"K1-2-u2-X02"},{"t":"운","mis":"K1-2-u2-X02"}],"explanation":["「밟」의 받침은 ㄹ과 ㅂ 두 개예요.","「어」는 받침이 없고 「운」은 받침이 ㄴ 하나예요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#2','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','『국어』 39쪽 — 같은 자음자가 겹쳐서 된 받침을 무엇이라고 하나요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 39쪽 — 같은 자음자가 겹쳐서 된 받침을 무엇이라고 하나요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["「낚」의 ㄲ처럼 같은 자음자가 겹치면 쌍받침이에요.","서로 다른 자음자 두 개가 겹받침이에요.","같은지 다른지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#3','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','『국어』 39쪽 — 서로 다른 두 개의 자음자로 이루어진 받침을 무엇이라고 하나요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":3,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 39쪽 — 서로 다른 두 개의 자음자로 이루어진 받침을 무엇이라고 하나요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["「밟」의 ㄼ처럼 서로 다른 자음자 두 개면 겹받침이에요.","같은 자음자가 겹친 것은 쌍받침이에요.","같은지 다른지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#4','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','『국어』 39쪽 — 「낚다」의 받침 ㄲ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":4,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 39쪽 — 「낚다」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"모음자","mis":"K1-2-u2-X03"}],"explanation":["ㄲ은 같은 자음자 ㄱ이 겹친 쌍받침이에요.","겹받침은 서로 다른 자음자 두 개예요. ㄲ은 자음자예요.","ㄱ과 ㄱ — 같은 자음자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
