INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#8','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',2,'match','auto','『국어』 42~43쪽 5번 — 두 낱말에 함께 들어갈 받침을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"『국어』 42~43쪽 5번 — 두 낱말에 함께 들어갈 받침을 이어 보세요.","pairs":[{"l":"부○다 · 이○다","r":"ㄺ"},{"l":"다○다 · 뚜○다","r":"ㅀ"},{"l":"짜○다 · 바○다","r":"ㄼ"},{"l":"약가○ · 어○다","r":"ㅄ"}],"mis":"K1-2-u2-X05","explanation":["붉다·읽다는 ㄺ, 닳다·뚫다는 ㅀ이에요.","짧다·밟다는 ㄼ, 약값·없다는 ㅄ이에요.","받침을 넣어 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#9','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C3',2,'mc','auto','『국어』 45쪽 — 「흙을 밟다.」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],false,'{"seq":9,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 — 「흙을 밟다.」를 바르게 읽은 것은?","options":[{"t":"[흘글 밥ː따]","correct":true},{"t":"[흐글 밥따]","mis":"K1-2-u2-X08"},{"t":"[흘글 발브따]","mis":"K1-2-u2-X07"}],"explanation":["「흙을」은 뒤에 모음이 와서 [흘글], 「밟다」는 [밥ː따]로 읽어요.","받침 하나를 빼먹거나 두 개를 다 소리 내면 안 돼요.","겹받침 뒤에 무엇이 오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#10','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',3,'error','auto','친구가 「넓」의 짜임을 「ㄴ + ㅓ + ㄹ」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X03']::text[],false,'{"seq":10,"concept":"K1-2-u2-C1","difficulty":3,"kind":"error","stem":"친구가 「넓」의 짜임을 「ㄴ + ㅓ + ㄹ」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침에 ㅂ이 빠졌어요 — 「넓」은 ㄴ + ㅓ + ㄼ이에요","correct":true,"mis_target":"K1-2-u2-X03"},{"t":"첫소리가 틀렸어요 — ㄷ이에요","mis":"K1-2-u2-X03"},{"t":"가운뎃소리가 틀렸어요 — ㅏ예요","mis":"K1-2-u2-X03"}],"explanation":["「넓」의 받침은 ㄹ과 ㅂ이 함께 있는 ㄼ이에요.","첫소리 ㄴ과 가운뎃소리 ㅓ는 맞아요.","받침 자리의 자음자를 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
