INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#8','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',4,'sa','auto','『국어』 43쪽 — 「짜◯다 · 바◯다」 두 낱말에 함께 들어갈 받침을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C1","difficulty":4,"kind":"sa","stem":"『국어』 43쪽 — 「짜◯다 · 바◯다」 두 낱말에 함께 들어갈 받침을 쓰세요.","answer":["ㄼ","ㄹㅂ"],"explanation":["ㄼ을 넣으면 「짧다」·「밟다」가 돼요.","ㄹ 하나만 넣으면 「짤다」·「발다」가 돼요.","받침 두 개를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#9','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C3',4,'sa','auto','『국어』 45쪽 — 「개미가 틀림없다.」를 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C3","difficulty":4,"kind":"sa","stem":"『국어』 45쪽 — 「개미가 틀림없다.」를 소리 나는 대로 쓰세요.","answer":["개미가 틀리멉따","[개미가 틀리멉따]","개미가틀리멉따","[개미가틀리멉따]","개미가 틀리멉따.","틀리멉따","[틀리멉따]"],"explanation":["「틀림없다」는 [틀리멉따]로 읽어요.","「없」의 ㅄ은 ㅂ만 소리 나요.","소리를 [ ] 안에 쓰기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#10','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',4,'essay','teacher','「낚다」와 「밟다」의 받침이 어떻게 다른지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C1","difficulty":4,"kind":"essay","stem":"「낚다」와 「밟다」의 받침이 어떻게 다른지 써 보세요.","answer_guide":{"answer":"예: 「낚」의 ㄲ은 같은 자음자가 겹친 쌍받침이고, 「밟」의 ㄼ은 서로 다른 자음자 두 개로 된 겹받침이에요.","scoring_points":["ㄲ을 쌍받침이라고 했는가","ㄼ을 겹받침이라고 했는가","같은 자음자·서로 다른 자음자로 구별했는가"]},"explanation":["같은 자음자가 겹치면 쌍받침이에요.","서로 다른 자음자 두 개면 겹받침이에요.","『국어』 39쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#1','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','『국어』 46쪽 — 환한 전등 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":1,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 46쪽 — 환한 전등 그림에 어울리는 문장은?","options":[{"t":"불빛이 밝다.","correct":true},{"t":"불빛이 밝따.","mis":"K1-2-u2-X04"},{"t":"불빛이 발따.","mis":"K1-2-u2-X04"}],"explanation":["「밝다」는 [박따]로 소리 나도 받침 ㄺ을 써요.","소리 나는 대로 쓰면 안 돼요.","낱말대로 써요."],"asset":{"type":"scene","icon":"💡","text":"환한 전등"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#2','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','『국어』 46쪽 — 넓은 들판 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":2,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 46쪽 — 넓은 들판 그림에 어울리는 문장은?","options":[{"t":"들판이 넓다.","correct":true},{"t":"들판이 널따.","mis":"K1-2-u2-X04"},{"t":"들판이 넙다.","mis":"K1-2-u2-X04"}],"explanation":["「넓다」는 [널따]로 소리 나도 받침 ㄼ을 써요.","소리 나는 대로 쓰면 안 돼요.","낱말대로 써요."],"asset":{"type":"scene","icon":"🌾","text":"넓은 들판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#3','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','『국어』 46쪽 — 아파서 누운 아이 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 46쪽 — 아파서 누운 아이 그림에 어울리는 문장은?","options":[{"t":"감기를 앓다.","correct":true},{"t":"감기를 알타.","mis":"K1-2-u2-X04"},{"t":"감기를 알다.","mis":"K1-2-u2-X06"}],"explanation":["아파서 누워 있으니 「감기를 앓다」예요. 받침은 ㅀ이에요.","「알다」는 「무엇을 안다」는 뜻의 다른 낱말이에요.","아픈 장면을 떠올려요."],"asset":{"type":"scene","icon":"🤒","text":"아파서 누운 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#4','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','『국어』 46쪽 — 빈 물컵 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X06','K1-2-u2-X04']::text[],false,'{"seq":4,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 46쪽 — 빈 물컵 그림에 어울리는 문장은?","options":[{"t":"물이 없다.","correct":true},{"t":"물이 업다.","mis":"K1-2-u2-X06"},{"t":"물이 업따.","mis":"K1-2-u2-X04"}],"explanation":["물컵이 비어 있으니 「물이 없다」예요. 받침은 ㅄ이에요.","「업다」는 「아기를 업다」처럼 등에 지는 뜻의 다른 낱말이에요.","뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🥛","text":"빈 물컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
