INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#8','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'mc','auto','『국어』 48쪽 3번 — 「닥과 병아리가 모이를 먹는다.」에서 잘못 쓴 글자를 고치면?',ARRAY['K1-2-u2-X05','K1-2-u2-X04']::text[],false,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 48쪽 3번 — 「닥과 병아리가 모이를 먹는다.」에서 잘못 쓴 글자를 고치면?","options":[{"t":"닭","correct":true},{"t":"닦","mis":"K1-2-u2-X05"},{"t":"닥","mis":"K1-2-u2-X04"}],"explanation":["「닭」은 받침에 ㄺ이 있는 낱말이에요.","「닥」은 소리 나는 대로 쓴 글자, 「닦」은 받침이 쌍받침이에요.","받침에 ㄹ을 더해요."],"asset":{"type":"scene","icon":"🐓🐥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#9','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'mc','auto','『국어』 48쪽 3번 — 「크레파스의 길이가 연필의 길이보다 짭다.」를 바르게 고치면?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":9,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 48쪽 3번 — 「크레파스의 길이가 연필의 길이보다 짭다.」를 바르게 고치면?","options":[{"t":"짧다","correct":true},{"t":"짤다","mis":"K1-2-u2-X04"},{"t":"짭다","mis":"K1-2-u2-X04"}],"explanation":["소리는 [짤따]여도 받침은 ㄼ으로 써요.","짤다·짭다는 소리 나는 대로 쓴 것이에요.","낱말대로 써요."],"asset":{"type":"scene","icon":"🖍️✏️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#10','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',3,'mc','auto','『국어』 48쪽 3번 — 「연필심이 달았다.」를 바르게 고치면?',ARRAY['K1-2-u2-X05','K1-2-u2-X06']::text[],false,'{"seq":10,"concept":"K1-2-u2-C2","difficulty":3,"kind":"mc","stem":"『국어』 48쪽 3번 — 「연필심이 달았다.」를 바르게 고치면?","options":[{"t":"닳았다","correct":true},{"t":"닭았다","mis":"K1-2-u2-X05"},{"t":"달았다","mis":"K1-2-u2-X06"}],"explanation":["연필심이 써서 줄어든 것이니 「닳았다」 — 받침은 ㅀ이에요.","「닭」의 받침 ㄺ과 헷갈리면 안 되고, 「달았다」는 맛이 달다는 뜻으로 들려요.","뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"✏️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#1','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',2,'mc','auto','『국어』 48쪽 3번 — 「필통에 연필이 업다.」를 바르게 고치면?',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":1,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 48쪽 3번 — 「필통에 연필이 업다.」를 바르게 고치면?","options":[{"t":"없다","correct":true},{"t":"엎다","mis":"K1-2-u2-X06"},{"t":"업다","mis":"K1-2-u2-X06"}],"explanation":["필통에 연필이 「없다」 — 받침은 ㅄ이에요.","「업다」는 등에 지는 것, 「엎다」는 뒤집는 것이라 뜻이 달라요.","뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"✏️👝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#2','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',2,'mc','auto','『국어』 47쪽 — 「학교 운동장이 ___.」에 바르게 쓴 낱말은?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":2,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 47쪽 — 「학교 운동장이 ___.」에 바르게 쓴 낱말은?","options":[{"t":"넓다","correct":true},{"t":"널따","mis":"K1-2-u2-X04"},{"t":"넒다","mis":"K1-2-u2-X05"}],"explanation":["운동장이 「넓다」 — 받침은 ㄼ이에요.","널따는 소리 나는 대로 쓴 것, 넒다는 받침을 바꿔 쓴 것이에요.","ㄹ 다음에 ㅂ이에요."],"asset":{"type":"scene","icon":"🏫"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#3','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'error','auto','「크레파스가 연필보다 짭다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「크레파스가 연필보다 짭다.」 무엇이 잘못되었나요?","options":[{"t":"소리 나는 대로 썼어요 — 「짧다」로 써야 해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「크레파스」를 빼야 해요","mis":"K1-2-u2-X06"},{"t":"맞게 쓴 문장이에요","mis":"K1-2-u2-X04"}],"explanation":["「짧다」는 [짤따]로 소리 나도 받침 ㄼ을 써요.","다른 낱말은 맞게 썼어요.","『국어』 48쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#4','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'error','auto','「닥과 병아리가 모이를 먹는다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06','K1-2-u2-X05']::text[],false,'{"seq":4,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「닥과 병아리가 모이를 먹는다.」 무엇이 잘못되었나요?","options":[{"t":"「닥」을 「닭」으로 고쳐야 해요 — 받침에 ㄹ을 더해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「모이」를 「모의」로 고쳐야 해요","mis":"K1-2-u2-X06"},{"t":"「병아리」를 고쳐야 해요","mis":"K1-2-u2-X05"}],"explanation":["「닭」은 받침이 ㄺ이에요.","모이와 병아리는 맞게 썼어요.","소리 나는 대로 쓴 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#5','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'match','auto','『국어』 48쪽 — 잘못 쓴 글자와 바르게 고친 글자를 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u2-C2","difficulty":3,"kind":"match","stem":"『국어』 48쪽 — 잘못 쓴 글자와 바르게 고친 글자를 이어 보세요.","pairs":[{"l":"닥","r":"닭"},{"l":"짭다","r":"짧다"},{"l":"달았다","r":"닳았다"},{"l":"업다","r":"없다"}],"mis":"K1-2-u2-X04","explanation":["닥→닭, 짭다→짧다예요.","달았다→닳았다, 업다→없다예요.","받침에 자음자 두 개를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#6','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'ox','auto','겹받침이 있는 낱말은 소리 나는 대로 써도 괜찮아요.',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":6,"concept":"K1-2-u2-C2","difficulty":3,"kind":"ox","stem":"겹받침이 있는 낱말은 소리 나는 대로 써도 괜찮아요.","answer":"X","reason_options":[{"t":"소리는 [업ː따]여도 쓸 때는 「없다」처럼 낱말대로 써야 하니까","correct":true},{"t":"소리 나는 대로 쓰면 더 쉬우니까","mis":"K1-2-u2-X04"}],"mis":"K1-2-u2-X04","explanation":["소리 나는 대로 쓰면 다른 뜻이 되거나 틀린 글자가 돼요.","쓸 때는 낱말대로 받침을 써요.","『국어』 48쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#7','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'mc','auto','겹받침이 있는 낱말을 바르게 익히지 않으면 어떤 일이 생길 수 있나요?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":7,"concept":"K1-2-u2-C2","difficulty":3,"kind":"mc","stem":"겹받침이 있는 낱말을 바르게 익히지 않으면 어떤 일이 생길 수 있나요?","options":[{"t":"다른 뜻을 전할 수도 있어요","correct":true},{"t":"아무 일도 생기지 않아요","mis":"K1-2-u2-X04"},{"t":"글씨만 조금 미워져요","mis":"K1-2-u2-X04"}],"explanation":["「없다」를 「업다」로 쓰면 등에 지는 뜻이 돼요.","받침은 뜻을 정확하게 전하는 데 중요해요.","지난 시간에 배운 것을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#8','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'sa','auto','『국어』 48쪽 — 「필통에 연필이 업다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"『국어』 48쪽 — 「필통에 연필이 업다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.","answer":["없다"],"explanation":["필통에 연필이 「없다」예요.","받침은 ㅄ이에요.","뜻을 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#9','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'sa','auto','『국어』 48쪽 — 「연필심이 달았다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"『국어』 48쪽 — 「연필심이 달았다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.","answer":["닳았다","연필심이 닳았다","연필심이 닳았다."],"explanation":["연필심이 「닳았다」예요.","받침은 ㅀ이에요.","써서 줄어든 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#10','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'essay','teacher','『국어』 46쪽 — 「밝다·넓다·앓다·없다」 가운데 하나를 넣어 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C2","difficulty":4,"kind":"essay","stem":"『국어』 46쪽 — 「밝다·넓다·앓다·없다」 가운데 하나를 넣어 문장을 쓰세요.","answer_guide":{"answer":"예: 오늘은 달빛이 밝다. / 우리 집 마당이 넓다. / 동생이 감기를 앓다. / 가방에 지우개가 없다. — 받침을 바르게 쓰고 뜻이 맞으면 맞아요.","scoring_points":["고른 낱말을 넣었는가","받침을 바르게 썼는가","문장의 뜻이 자연스러운가"]},"explanation":["소리 나는 대로 쓰지 않고 낱말대로 써요.","뜻에 맞는 장면을 떠올려요.","쓴 뒤 받침을 한 번 더 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#1','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「대단한 참외씨」 — 참외씨의 꿈은 무엇인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":1,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「대단한 참외씨」 — 참외씨의 꿈은 무엇인가요?","options":[{"t":"흙 속에 들어가서 달고 맛있는 참외가 되는 것","correct":true},{"t":"철이 배 속에서 사는 것","mis":"K1-2-u2-X13"},{"t":"나비처럼 하늘을 나는 것","mis":"K1-2-u2-X13"}],"explanation":["참외씨가 「제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요.」라고 말했어요.","철이 배 속이나 하늘을 나는 것은 꿈이 아니에요.","참외씨가 한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#2','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「대단한 참외씨」 — 먼지 할아버지는 세상을 어떤 곳이라고 했나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":2,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「대단한 참외씨」 — 먼지 할아버지는 세상을 어떤 곳이라고 했나요?","options":[{"t":"아주 넓고 위험한 곳","correct":true},{"t":"아주 작고 조용한 곳","mis":"K1-2-u2-X13"},{"t":"달고 맛있는 곳","mis":"K1-2-u2-X13"}],"explanation":["「세상은 아주 넓고 위험하거든.」이라고 했어요.","작고 조용한 곳이나 맛있는 곳이 아니에요.","먼지 할아버지가 한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#3','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「대단한 참외씨」 — 참외씨가 마지막으로 도착한 곳은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":3,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「대단한 참외씨」 — 참외씨가 마지막으로 도착한 곳은?","options":[{"t":"흙 속","correct":true},{"t":"나비 날개","mis":"K1-2-u2-X13"},{"t":"고양이 꼬리","mis":"K1-2-u2-X13"}],"explanation":["참외씨는 마침내 흙 속에 들어갔어요.","나비 날개와 고양이 꼬리는 가는 길에 매달린 곳이에요.","마지막 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["철이가 먹은 참외의 씨 하나가 탈출했어요.","참외씨는 재빨리 팔꿈치로 도망갔어요.","먼지 할아버지를 만나 흙이 어디 있는지 물었어요.","바람에 휘리릭 날아가 고양이 꼬리, 나비 날개에 매달렸어요.","참외씨는 마침내 흙 속에 들어갔어요."],"title":"대단한 참외씨 (임수정 글·전미화 그림) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#4','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','『국어』 61쪽 — 「흙이 어디 있는지 아세요?」에서 「흙이」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 61쪽 — 「흙이 어디 있는지 아세요?」에서 「흙이」를 바르게 읽은 것은?","options":[{"t":"[흘기]","correct":true},{"t":"[흐기]","mis":"K1-2-u2-X08"},{"t":"[흑이]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음 「이」가 오면 ㄱ이 넘어가 [흘기]로 읽어요.","ㄹ을 빼먹거나 글자대로 끊어 읽으면 안 돼요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#5','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'mc','auto','『국어』 61쪽 — 「흙 속에 들어가서」에서 「흙 속에」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":5,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 61쪽 — 「흙 속에 들어가서」에서 「흙 속에」를 바르게 읽은 것은?","options":[{"t":"[흑쏘게]","correct":true},{"t":"[흘쏘게]","mis":"K1-2-u2-X07"},{"t":"[흐쏘게]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 자음 ㅅ이 오면 ㄺ 가운데 ㄱ만 소리 나 [흑쏘게]예요.","ㄹ로 읽거나 받침을 빼먹으면 안 돼요.","「흙이」와 견주어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#6','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'match','auto','『국어』 60쪽 낱말 알기 — 낱말과 그 뜻을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C3","difficulty":2,"kind":"match","stem":"『국어』 60쪽 낱말 알기 — 낱말과 그 뜻을 이어 보세요.","pairs":[{"l":"간신히","r":"겨우. 매우 힘들게."},{"l":"하마터면","r":"조금만 잘못했더라면."},{"l":"무시무시하다","r":"아주 많이 무섭다."}],"mis":"K1-2-u2-X16","explanation":["간신히는 겨우, 하마터면은 조금만 잘못했더라면이에요.","무시무시하다는 아주 많이 무섭다는 뜻이에요.","낱말이 나온 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
