INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#9','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','「대단한 참외씨」 — 참외씨가 먼지 할아버지에게 물어본 것은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「대단한 참외씨」 — 참외씨가 먼지 할아버지에게 물어본 것은?","options":[{"t":"흙이 어디 있는지","correct":true},{"t":"철이가 어디 있는지","mis":"K1-2-u2-X13"},{"t":"참외가 얼마인지","mis":"K1-2-u2-X13"}],"explanation":["「그럼, 혹시 흙이 어디 있는지 아세요?」 하고 물었어요.","철이나 참외 값을 물어보지 않았어요.","참외씨가 한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#10','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',3,'mc','auto','『국어』 54쪽 — 파란색 글자 「흙」·「넓」에 주의하며 읽어야 하는 까닭은?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":10,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"『국어』 54쪽 — 파란색 글자 「흙」·「넓」에 주의하며 읽어야 하는 까닭은?","options":[{"t":"받침에 자음자가 두 개 있어 바르게 읽어야 하니까","correct":true},{"t":"파란색 글자는 크게 읽어야 하니까","mis":"K1-2-u2-X07"},{"t":"받침을 소리 내지 않아야 하니까","mis":"K1-2-u2-X07"}],"explanation":["겹받침 낱말은 바르게 읽어야 뜻이 정확하게 전해져요.","색깔 때문도, 받침을 안 읽으려는 것도 아니에요.","겹받침을 찾아봐요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#1','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C5',2,'mc','auto','「대단한 참외씨」 — 탈출한 참외씨가 처음 도망간 곳은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":1,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「대단한 참외씨」 — 탈출한 참외씨가 처음 도망간 곳은?","options":[{"t":"팔꿈치","correct":true},{"t":"고양이 꼬리","mis":"K1-2-u2-X13"},{"t":"흙 속","mis":"K1-2-u2-X13"}],"explanation":["참외씨는 재빨리 팔꿈치로 도망갔어요.","고양이 꼬리와 흙 속은 나중에 간 곳이에요.","둘째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["철이가 먹은 참외의 씨 하나가 탈출했어요.","참외씨는 재빨리 팔꿈치로 도망갔어요.","먼지 할아버지를 만나 흙이 어디 있는지 물었어요.","바람에 휘리릭 날아가 고양이 꼬리, 나비 날개에 매달렸어요.","참외씨는 마침내 흙 속에 들어갔어요."],"title":"대단한 참외씨 (임수정 글·전미화 그림) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
