INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#3','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'error','auto','친구가 「흙이 어디 있는지」를 [흐기]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":3,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「흙이 어디 있는지」를 [흐기]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 모음 「이」가 와서 [흘기]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X08"},{"t":"[흙이]로 글자대로 끊어 읽어야 해요","mis":"K1-2-u2-X08"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X08"}],"explanation":["겹받침 뒤에 모음이 오면 받침 하나가 넘어가 둘 다 소리 나요.","ㄹ을 빼먹으면 안 돼요.","『국어』 61쪽 바르게 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#4','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'error','auto','친구가 「흙 속에」를 [흘쏘게]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「흙 속에」를 [흘쏘게]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 자음 ㅅ이 와서 ㄱ만 소리 나 [흑쏘게]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X07"},{"t":"[흘그쏘게]처럼 둘 다 읽어야 해요","mis":"K1-2-u2-X07"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X07"}],"explanation":["겹받침 뒤에 자음이 오면 하나만 소리 나요.","「흙」은 이때 ㄱ이 소리 나요.","「흙이」와 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#5','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C5',3,'mc','auto','참외씨는 어떤 마음으로 흙을 찾아다녔을까요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":5,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"참외씨는 어떤 마음으로 흙을 찾아다녔을까요?","options":[{"t":"참외가 되고 싶은 꿈을 꼭 이루고 싶은 마음","correct":true},{"t":"철이를 놀리고 싶은 마음","mis":"K1-2-u2-X13"},{"t":"그냥 바람을 타고 싶은 마음","mis":"K1-2-u2-X13"}],"explanation":["참외씨의 말에서 꿈을 이루고 싶은 마음을 알 수 있어요.","참외씨가 한 말과 행동으로 짐작해요.","참외씨의 꿈을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#6','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'match','auto','낱말과 바르게 읽은 소리를 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C3","difficulty":3,"kind":"match","stem":"낱말과 바르게 읽은 소리를 이어 보세요.","pairs":[{"l":"흙이","r":"[흘기]"},{"l":"흙 속에","r":"[흑쏘게]"},{"l":"넓다","r":"[널따]"}],"mis":"K1-2-u2-X07","explanation":["흙이는 [흘기], 흙 속에는 [흑쏘게]예요.","넓다는 [널따]예요.","뒤에 무엇이 오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#7','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'ox','auto','「흙이」와 「흙 속에」에서 「흙」의 받침 소리는 서로 달라요.',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":7,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"「흙이」와 「흙 속에」에서 「흙」의 받침 소리는 서로 달라요.","answer":"O","reason_options":[{"t":"뒤에 모음이 오면 [흘기], 자음이 오면 [흑쏘게]로 소리 나니까","correct":true},{"t":"「흙」은 언제나 [흑]으로만 읽으니까","mis":"K1-2-u2-X08"}],"mis":"K1-2-u2-X08","explanation":["같은 「흙」이어도 뒤에 오는 소리에 따라 달라져요.","그래서 받침에 주의하며 읽어야 해요.","『국어』 61쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#8','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C5',4,'sa','auto','참외씨는 흙 속에 들어가서 무엇이 되고 싶었나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C5","difficulty":4,"kind":"sa","stem":"참외씨는 흙 속에 들어가서 무엇이 되고 싶었나요? 한 낱말로 쓰세요.","answer":["참외","달고 맛있는 참외","맛있는 참외","달고맛있는참외","맛있는참외"],"explanation":["달고 맛있는 참외가 되고 싶었어요.","흙이나 나비가 아니에요.","참외씨가 한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"참외씨","text":"그럼, 혹시 흙이 어디 있는지 아세요? 제 꿈은 흙 속에 들어가서 달고 맛있는 참외가 되는 거예요."},{"who":"먼지 할아버지","text":"세상은 아주 넓고 위험하거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#9','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','『국어』 61쪽 — 내가 참외씨라면 어디로 가고 싶은지, 그 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"『국어』 61쪽 — 내가 참외씨라면 어디로 가고 싶은지, 그 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 나는 할머니 댁 밭에 가고 싶어요. 흙이 많아서 맛있는 참외가 될 수 있으니까요. — 가고 싶은 곳과 까닭이 있으면 맞아요.","scoring_points":["가고 싶은 곳을 썼는가","까닭을 썼는가","참외씨의 꿈과 이어지는가"]},"explanation":["참외씨의 꿈을 떠올려 가고 싶은 곳을 정해요.","까닭을 「~니까」로 이어 써요.","친구의 생각과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#10','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',4,'essay','teacher','『국어』 60쪽 — 「하마터면」을 넣어 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C3","difficulty":4,"kind":"essay","stem":"『국어』 60쪽 — 「하마터면」을 넣어 문장을 쓰세요.","answer_guide":{"answer":"예: 하마터면 계단에서 넘어질 뻔했다. — 「~할 뻔했다」와 어울리면 맞아요.","scoring_points":["하마터면을 넣었는가","「~할 뻔했다」와 어울리는가","문장이 자연스러운가"]},"explanation":["하마터면은 「조금만 잘못했더라면」이라는 뜻이에요.","그래서 「~할 뻔했다」와 함께 써요.","교과서 예문을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#1','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','『국어』 63쪽 2번 — 이 글을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":1,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 63쪽 2번 — 이 글을 쓴 사람은 누구인가요?","options":[{"t":"김서연","correct":true},{"t":"서연이 동생","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["글 끝에 「1학년 김서연」이라고 쓰여 있어요.","동생은 글에 나오는 사람이에요.","글의 끝을 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#2','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','『국어』 63쪽 2번 — 이 글의 제목은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":2,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 63쪽 2번 — 이 글의 제목은 무엇인가요?","options":[{"t":"사용한 물건을 제자리에 두자","correct":true},{"t":"풀과 가위","mis":"K1-2-u2-X11"},{"t":"내 동생","mis":"K1-2-u2-X11"}],"explanation":["제목은 「사용한 물건을 제자리에 두자」예요.","풀과 가위, 동생은 글 속에 나오는 것이에요.","글 맨 위를 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#3','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','글을 쓴 사람을 무엇이라고 하나요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":3,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"글을 쓴 사람을 무엇이라고 하나요?","options":[{"t":"글쓴이","correct":true},{"t":"제목","mis":"K1-2-u2-X12"},{"t":"인물","mis":"K1-2-u2-X12"}],"explanation":["글을 쓴 사람을 글쓴이라고 해요.","제목은 글의 이름이고, 인물은 글에 나오는 사람이에요.","『국어』 63쪽에서 배웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#4','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','서연이는 물건을 쓰고 나서 어떻게 하나요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":4,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"서연이는 물건을 쓰고 나서 어떻게 하나요?","options":[{"t":"제자리에 둡니다","correct":true},{"t":"아무 데나 둡니다","mis":"K1-2-u2-X11"},{"t":"친구에게 줍니다","mis":"K1-2-u2-X11"}],"explanation":["「나는 물건을 쓰고 나서 제자리에 둡니다.」라고 했어요.","아무 데나 두는 것은 동생이에요.","첫째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#5','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'match','auto','『국어』 63쪽 2번 — 사람과 습관을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":2,"kind":"match","stem":"『국어』 63쪽 2번 — 사람과 습관을 이어 보세요.","pairs":[{"l":"서연이","r":"물건을 쓰고 나서 제자리에 둡니다."},{"l":"동생","r":"물건을 쓰고 나서 아무 데나 둡니다."},{"l":"제자리에 두면","r":"다음에 빨리 찾을 수 있습니다."}],"mis":"K1-2-u2-X11","explanation":["서연이는 제자리에 두고 동생은 아무 데나 둬요.","제자리에 두면 빨리 찾을 수 있어요.","글을 다시 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#6','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','동생은 다음에 물건을 쓰려면 어떻게 되나요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":6,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"동생은 다음에 물건을 쓰려면 어떻게 되나요?","options":[{"t":"한참을 찾아야 합니다","correct":true},{"t":"빨리 찾을 수 있습니다","mis":"K1-2-u2-X11"},{"t":"새 물건을 삽니다","mis":"K1-2-u2-X11"}],"explanation":["아무 데나 두어서 한참을 찾아야 해요.","빨리 찾는 것은 서연이예요.","넷째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#7','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','『국어』 64쪽 4번 — 이 글의 글쓴이가 하고 싶은 말은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":7,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 64쪽 4번 — 이 글의 글쓴이가 하고 싶은 말은?","options":[{"t":"물건을 쓰고 나서 제자리에 두자","correct":true},{"t":"동생과 사이좋게 지내자","mis":"K1-2-u2-X11"},{"t":"풀과 가위를 새로 사자","mis":"K1-2-u2-X11"}],"explanation":["제목과 끝부분에 하고 싶은 말이 나타나 있어요.","동생 이야기는 까닭을 보여 주는 있었던 일이에요.","제목을 다시 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#8','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','『국어』 64쪽 3번 — 글쓴이가 하고 싶은 말을 찾는 방법이 아닌 것은?',ARRAY['K1-2-u2-X10']::text[],false,'{"seq":8,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 64쪽 3번 — 글쓴이가 하고 싶은 말을 찾는 방법이 아닌 것은?","options":[{"t":"글자 수를 세어 봐요","correct":true},{"t":"글의 제목을 살펴봐요","mis":"K1-2-u2-X10"},{"t":"글쓴이가 이 글을 쓴 까닭을 찾아봐요","mis":"K1-2-u2-X10"}],"explanation":["글쓴이·제목·쓴 까닭을 살펴 하고 싶은 말을 찾아요.","글자 수는 하고 싶은 말과 상관없어요.","세 가지 방법을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#9','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'ox','auto','글쓴이의 생각은 글의 제목에 나타나기도 해요.',ARRAY['K1-2-u2-X10']::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":2,"kind":"ox","stem":"글쓴이의 생각은 글의 제목에 나타나기도 해요.","answer":"O","reason_options":[{"t":"「사용한 물건을 제자리에 두자」처럼 제목에 하고 싶은 말이 담기니까","correct":true},{"t":"제목은 글의 내용과 상관없으니까","mis":"K1-2-u2-X10"}],"mis":"K1-2-u2-X10","explanation":["제목에 하고 싶은 말이 그대로 담길 때가 많아요.","그래서 제목을 꼭 살펴봐요.","『국어』 64쪽 알아 두기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#10','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',3,'mc','auto','「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말은?","options":[{"t":"자전거를 안전하게 타자","correct":true},{"t":"새 자전거를 사자","mis":"K1-2-u2-X11"},{"t":"자전거보다 달리기를 하자","mis":"K1-2-u2-X11"}],"explanation":["제목과 마지막 문장에 하고 싶은 말이 나타나 있어요.","새 자전거나 달리기 이야기는 없어요.","제목과 끝 문장을 함께 봐요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#1','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',2,'mc','auto','서연이가 이 글을 쓴 까닭은 무엇일까요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":1,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"서연이가 이 글을 쓴 까닭은 무엇일까요?","options":[{"t":"물건을 쉽고 빠르게 찾을 수 있게 하려고","correct":true},{"t":"동생을 혼내 주려고","mis":"K1-2-u2-X11"},{"t":"풀과 가위를 자랑하려고","mis":"K1-2-u2-X11"}],"explanation":["제자리에 두어야 쉽고 빠르게 찾을 수 있다고 했어요.","동생을 혼내거나 자랑하려는 글이 아니에요.","마지막 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#2','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',2,'mc','auto','「자전거를 안전하게 타자」에서 안전하게 타는 방법이 아닌 것은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":2,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「자전거를 안전하게 타자」에서 안전하게 타는 방법이 아닌 것은?","options":[{"t":"빠른 속도로 달린다","correct":true},{"t":"안전모를 꼭 쓴다","mis":"K1-2-u2-X11"},{"t":"신호등을 꼭 지킨다","mis":"K1-2-u2-X11"}],"explanation":["적당한 속도로 타야 한다고 했어요.","안전모와 신호등은 글에 나온 방법이에요.","셋째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#3','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'error','auto','친구가 「서연이가 하고 싶은 말은 ‘내 동생은 물건을 아무 데나 둡니다’예요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X11','K1-2-u2-X12']::text[],false,'{"seq":3,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"친구가 「서연이가 하고 싶은 말은 ‘내 동생은 물건을 아무 데나 둡니다’예요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"그것은 있었던 일이에요 — 하고 싶은 말은 「물건을 제자리에 두자」예요","correct":true,"mis_target":"K1-2-u2-X11"},{"t":"맞게 말했어요 — 동생 이야기가 제일 길어요","mis":"K1-2-u2-X11"},{"t":"글쓴이는 동생이에요","mis":"K1-2-u2-X12"}],"explanation":["동생 이야기는 까닭을 보여 주려고 쓴 있었던 일이에요.","하고 싶은 말은 제목에 담겨 있어요.","「하라는 말인가, 있었던 일인가」 물어봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#4','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'error','auto','친구가 「하고 싶은 말은 첫 문장 ‘나는 물건을 쓰고 나서 제자리에 둡니다’예요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X10','K1-2-u2-X12']::text[],false,'{"seq":4,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"친구가 「하고 싶은 말은 첫 문장 ‘나는 물건을 쓰고 나서 제자리에 둡니다’예요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"첫 문장만 보았어요 — 끝까지 읽고 제목과 이어 「제자리에 두자」를 찾아요","correct":true,"mis_target":"K1-2-u2-X10"},{"t":"글쓴이를 잘못 알았어요","mis":"K1-2-u2-X12"},{"t":"맞게 말했어요","mis":"K1-2-u2-X10"}],"explanation":["첫 문장은 서연이의 습관이에요.","끝까지 읽고 제목·쓴 까닭과 이어야 해요.","제목을 다시 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#5','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'mc','auto','「자전거를 안전하게 타자」에서 자전거를 타면 좋은 점은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"「자전거를 안전하게 타자」에서 자전거를 타면 좋은 점은?","options":[{"t":"몸도 건강해지고 환경 오염도 줄일 수 있어요","correct":true},{"t":"안전모를 안 써도 돼요","mis":"K1-2-u2-X11"},{"t":"신호등을 안 지켜도 돼요","mis":"K1-2-u2-X11"}],"explanation":["첫째 줄에 좋은 점이 나와요.","안전모와 신호등은 꼭 지켜야 할 일이에요.","첫째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#6','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'match','auto','『국어』 64쪽 — 하고 싶은 말을 찾는 방법과 서연이 글에서 찾은 것을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C4","difficulty":3,"kind":"match","stem":"『국어』 64쪽 — 하고 싶은 말을 찾는 방법과 서연이 글에서 찾은 것을 이어 보세요.","pairs":[{"l":"글쓴이","r":"김서연"},{"l":"제목","r":"사용한 물건을 제자리에 두자"},{"l":"글을 쓴 까닭","r":"물건을 쉽고 빠르게 찾으려고"}],"mis":"K1-2-u2-X12","explanation":["글쓴이는 김서연, 제목은 「사용한 물건을 제자리에 두자」예요.","쓴 까닭은 물건을 쉽고 빠르게 찾으려는 거예요.","세 가지를 이으면 하고 싶은 말이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#7','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'ox','auto','글쓴이가 하고 싶은 말은 언제나 글의 첫 문장에만 있어요.',ARRAY['K1-2-u2-X10']::text[],false,'{"seq":7,"concept":"K1-2-u2-C4","difficulty":3,"kind":"ox","stem":"글쓴이가 하고 싶은 말은 언제나 글의 첫 문장에만 있어요.","answer":"X","reason_options":[{"t":"끝까지 읽고 제목·쓴 까닭과 이어야 찾을 수 있으니까","correct":true},{"t":"첫 문장이 가장 중요하니까","mis":"K1-2-u2-X10"}],"mis":"K1-2-u2-X10","explanation":["하고 싶은 말은 제목이나 끝부분에 나타나기도 해요.","첫 문장만 보면 놓칠 수 있어요.","끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#8','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'sa','auto','서연이가 쓴 글의 제목을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C4","difficulty":4,"kind":"sa","stem":"서연이가 쓴 글의 제목을 쓰세요.","answer":["사용한 물건을 제자리에 두자","사용한물건을제자리에두자"],"explanation":["제목은 「사용한 물건을 제자리에 두자」예요.","제목에 하고 싶은 말이 담겨 있어요.","글 맨 위를 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#9','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','서연이가 하고 싶은 말을 까닭과 이어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"서연이가 하고 싶은 말을 까닭과 이어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 물건을 쉽고 빠르게 찾을 수 있게 쓰고 나서 제자리에 두자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「제자리에 두자」는 말이 있는가","까닭(쉽고 빠르게 찾기)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","끝 줄이 까닭이에요.","둘을 「~게 ~하자」로 이어요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#10','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말을 까닭과 이어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말을 까닭과 이어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 다치지 않게 안전모를 쓰고 신호등을 지키며 자전거를 안전하게 타자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「안전하게 타자」는 말이 있는가","까닭(다치지 않게)을 이었는가","글의 내용과 맞는가"]},"explanation":["제목이 하고 싶은 말이에요.","안전하게 타지 않으면 다칠 수 있다는 것이 까닭이에요.","제목과 끝 문장을 이어요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#1','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「다니엘의 멋진 날」 — 이웃들은 다니엘에게 어떻게 인사하나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":1,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「다니엘의 멋진 날」 — 이웃들은 다니엘에게 어떻게 인사하나요?","options":[{"t":"「멋진 날 보내렴!」","correct":true},{"t":"「잘 가, 다니엘!」","mis":"K1-2-u2-X13"},{"t":"「조심해서 다녀라!」","mis":"K1-2-u2-X13"}],"explanation":["이웃들은 「멋진 날 보내렴!」 하고 인사해요.","다른 인사말은 나오지 않아요.","둘째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["다니엘은 여러 이웃과 잘 알고 지내요.","할머니 집에 갈 때면 이웃들이 「멋진 날 보내렴!」 하고 인사해요.","다니엘은 이웃들에게 「어떤 날이 멋진 날이에요?」 하고 물어요.","이웃들은 저마다 자기가 생각하는 멋진 날을 말해 줘요."],"title":"다니엘의 멋진 날 (미카 아처 글·그림, 이상희 옮김) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#2','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「다니엘의 멋진 날」 — 다니엘은 이웃들에게 무엇을 물어보았나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":2,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「다니엘의 멋진 날」 — 다니엘은 이웃들에게 무엇을 물어보았나요?","options":[{"t":"어떤 날이 멋진 날인지","correct":true},{"t":"할머니 집이 어디인지","mis":"K1-2-u2-X13"},{"t":"지금 몇 시인지","mis":"K1-2-u2-X13"}],"explanation":["「어떤 날이 멋진 날이에요?」 하고 물었어요.","할머니 집이나 시간을 묻지 않았어요.","셋째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["다니엘은 여러 이웃과 잘 알고 지내요.","할머니 집에 갈 때면 이웃들이 「멋진 날 보내렴!」 하고 인사해요.","다니엘은 이웃들에게 「어떤 날이 멋진 날이에요?」 하고 물어요.","이웃들은 저마다 자기가 생각하는 멋진 날을 말해 줘요."],"title":"다니엘의 멋진 날 (미카 아처 글·그림, 이상희 옮김) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#3','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','에마 누나가 말한 멋진 날은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":3,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"에마 누나가 말한 멋진 날은?","options":[{"t":"바람이 씽씽 불어서 연 날리기 좋은 날","correct":true},{"t":"하늘이 맑아서 페인트칠하기 좋은 날","mis":"K1-2-u2-X13"},{"t":"모두들 안전하게 귀가하는 날","mis":"K1-2-u2-X13"}],"explanation":["에마 누나는 연 날리기 좋은 날이라고 했어요.","페인트칠은 산체스 부인, 귀가는 안전 요원의 말이에요.","에마 누나의 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#4','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','안전 요원이 말한 멋진 날은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":4,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"안전 요원이 말한 멋진 날은?","options":[{"t":"모두들 안전하게 귀가하는 날","correct":true},{"t":"바람이 씽씽 부는 날","mis":"K1-2-u2-X13"},{"t":"페인트칠하기 좋은 날","mis":"K1-2-u2-X13"}],"explanation":["「나의 멋진 날은 모두들 안전하게 귀가하는 날.」이라고 했어요.","다른 인물의 말과 헷갈리면 안 돼요.","안전 요원의 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#5','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'match','auto','『국어』 72쪽 — 인물과 그 인물이 생각하는 멋진 날을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"『국어』 72쪽 — 인물과 그 인물이 생각하는 멋진 날을 이어 보세요.","pairs":[{"l":"에마 누나","r":"바람이 씽씽 불어서 연 날리기 좋은 날"},{"l":"산체스 부인","r":"하늘이 맑아서 페인트칠하기 좋은 날"},{"l":"안전 요원","r":"모두들 안전하게 귀가하는 날"},{"l":"할머니","r":"다니엘이 꼭 안아 주는 날"}],"mis":"K1-2-u2-X13","explanation":["에마 누나는 연, 산체스 부인은 페인트칠이에요.","안전 요원은 안전한 귀가, 할머니는 다니엘이 안아 주는 날이에요.","인물이 하는 일과 말을 함께 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#6','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'match','auto','『국어』 71쪽 낱말 알기 — 낱말과 그 뜻을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"『국어』 71쪽 낱말 알기 — 낱말과 그 뜻을 이어 보세요.","pairs":[{"l":"요원","r":"어떤 일을 하는 데 꼭 필요한 사람."},{"l":"귀가","r":"집으로 돌아감."},{"l":"건널목","r":"길을 건널 수 있게 정해진 곳."}],"mis":"K1-2-u2-X16","explanation":["요원은 꼭 필요한 사람, 귀가는 집으로 돌아감이에요.","건널목은 길을 건널 수 있게 정해진 곳이에요.","낱말이 나온 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#7','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','『국어』 72쪽 — 인물의 생각을 알아보려면 무엇을 살펴봐야 하나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":7,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"『국어』 72쪽 — 인물의 생각을 알아보려면 무엇을 살펴봐야 하나요?","options":[{"t":"인물이 한 말이나 행동","correct":true},{"t":"그림의 색깔","mis":"K1-2-u2-X13"},{"t":"책의 쪽수","mis":"K1-2-u2-X13"}],"explanation":["어떤 인물이 나오는지 찾고, 인물이 한 말이나 행동을 살펴봐요.","색깔이나 쪽수로는 생각을 알 수 없어요.","알아 두기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#8','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','산체스 부인이 페인트칠하기 좋은 날이라고 한 까닭은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":8,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"산체스 부인이 페인트칠하기 좋은 날이라고 한 까닭은?","options":[{"t":"하늘이 맑아서","correct":true},{"t":"바람이 씽씽 불어서","mis":"K1-2-u2-X13"},{"t":"비가 와서","mis":"K1-2-u2-X13"}],"explanation":["「하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다.」라고 했어요.","바람이 씽씽 부는 것은 에마 누나의 말이에요.","산체스 부인의 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#9','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','『국어』 71쪽 — 다니엘에게 멋진 날은 어떤 날일까요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"『국어』 71쪽 — 다니엘에게 멋진 날은 어떤 날일까요?","options":[{"t":"할머니 집에 가는 날","correct":true},{"t":"페인트칠하는 날","mis":"K1-2-u2-X13"},{"t":"비가 오는 날","mis":"K1-2-u2-X13"}],"explanation":["다니엘은 할머니 집에 가는 날을 멋진 날이라고 생각했을 거예요.","페인트칠은 산체스 부인의 멋진 날이에요.","다니엘이 어디에 가는지 떠올려요."],"asset":{"type":"passage","lines":["다니엘은 여러 이웃과 잘 알고 지내요.","할머니 집에 갈 때면 이웃들이 「멋진 날 보내렴!」 하고 인사해요.","다니엘은 이웃들에게 「어떤 날이 멋진 날이에요?」 하고 물어요.","이웃들은 저마다 자기가 생각하는 멋진 날을 말해 줘요."],"title":"다니엘의 멋진 날 (미카 아처 글·그림, 이상희 옮김) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#10','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',3,'mc','auto','이웃들이 말한 멋진 날이 저마다 다른 까닭은?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":10,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"이웃들이 말한 멋진 날이 저마다 다른 까닭은?","options":[{"t":"사람마다 좋아하고 중요하게 여기는 것이 달라서","correct":true},{"t":"한 사람만 맞게 말해서","mis":"K1-2-u2-X14"},{"t":"다니엘이 잘못 물어서","mis":"K1-2-u2-X14"}],"explanation":["질문은 하나여도 대답은 여러 가지일 수 있어요.","누가 틀린 것이 아니에요.","인물마다 하는 일을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#1','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',2,'blank','auto','『국어』 71쪽 — 빈칸에 알맞은 낱말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#2','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',2,'mc','auto','『국어』 73쪽 「상호 존중과 배려」 — 나와 생각이 다른 친구에게는 어떻게 할까요?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":2,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"『국어』 73쪽 「상호 존중과 배려」 — 나와 생각이 다른 친구에게는 어떻게 할까요?","options":[{"t":"생각이 다를 수 있다고 여기고 존중해요","correct":true},{"t":"「틀렸어!」라고 말해요","mis":"K1-2-u2-X14"},{"t":"친구의 말을 듣지 않아요","mis":"K1-2-u2-X14"}],"explanation":["여러 가지 생각이 어울릴 때 세상이 더 아름다워져요.","다른 생각을 틀렸다고 하면 안 돼요.","다니엘의 이웃들을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#3','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'error','auto','친구가 「에마 누나의 멋진 날은 ‘페인트칠하기 좋은 날’이에요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X13','K1-2-u2-X14']::text[],false,'{"seq":3,"concept":"K1-2-u2-C5","difficulty":3,"kind":"error","stem":"친구가 「에마 누나의 멋진 날은 ‘페인트칠하기 좋은 날’이에요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"그것은 산체스 부인의 말이에요 — 에마 누나는 연 날리기 좋은 날이에요","correct":true,"mis_target":"K1-2-u2-X13"},{"t":"맞게 말했어요","mis":"K1-2-u2-X13"},{"t":"에마 누나는 멋진 날을 말하지 않았어요","mis":"K1-2-u2-X14"}],"explanation":["인물마다 한 말을 나누어 살펴봐야 해요.","말한 사람을 헷갈리면 생각도 헷갈려요.","말풍선의 이름을 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#4','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'error','auto','친구가 「안전 요원의 멋진 날이 에마 누나와 다르니까 안전 요원이 틀렸어요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":4,"concept":"K1-2-u2-C5","difficulty":3,"kind":"error","stem":"친구가 「안전 요원의 멋진 날이 에마 누나와 다르니까 안전 요원이 틀렸어요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"물음은 하나여도 생각은 여러 가지일 수 있어요 — 틀린 것이 아니에요","correct":true,"mis_target":"K1-2-u2-X14"},{"t":"맞게 말했어요 — 답은 하나뿐이에요","mis":"K1-2-u2-X14"},{"t":"안전 요원은 멋진 날을 말하지 않았어요","mis":"K1-2-u2-X13"}],"explanation":["같은 물음에도 사람마다 대답이 달라요.","다른 생각은 틀린 것이 아니라 다른 것이에요.","지도서의 「사고의 다양성」이에요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#5','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'mc','auto','안전 요원의 말을 보면 안전 요원이 중요하게 여기는 것은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":5,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"안전 요원의 말을 보면 안전 요원이 중요하게 여기는 것은?","options":[{"t":"사람들이 다치지 않고 안전한 것","correct":true},{"t":"연을 높이 날리는 것","mis":"K1-2-u2-X13"},{"t":"집을 예쁘게 칠하는 것","mis":"K1-2-u2-X13"}],"explanation":["모두들 안전하게 귀가하는 날을 멋진 날이라고 했어요.","연은 에마 누나, 칠하기는 산체스 부인이에요.","인물의 말에서 짐작해요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#6','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'ox','auto','같은 물음에도 사람마다 대답이 다를 수 있어요.',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":3,"kind":"ox","stem":"같은 물음에도 사람마다 대답이 다를 수 있어요.","answer":"O","reason_options":[{"t":"이웃들이 저마다 다른 멋진 날을 말했으니까","correct":true},{"t":"물음이 하나면 답도 하나뿐이니까","mis":"K1-2-u2-X14"}],"mis":"K1-2-u2-X14","explanation":["다니엘의 물음 하나에 이웃들이 여러 가지로 대답했어요.","생각이 다른 것을 존중해요.","『국어』 72쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#7','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'mc','auto','동기 유발 — 「비가 오는 일요일 아침이었습니다.」 다음 문장을 친구마다 다르게 말했어요. 어떻게 생각해야 할까요?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":7,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"동기 유발 — 「비가 오는 일요일 아침이었습니다.」 다음 문장을 친구마다 다르게 말했어요. 어떻게 생각해야 할까요?","options":[{"t":"생각은 여러 가지일 수 있어요","correct":true},{"t":"내 문장만 맞아요","mis":"K1-2-u2-X14"},{"t":"가장 먼저 말한 친구 문장만 맞아요","mis":"K1-2-u2-X14"}],"explanation":["친구마다 이어 말한 문장이 다를 수 있어요.","하나만 맞는 것이 아니에요.","친구의 생각과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#8','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'sa','auto','『국어』 71쪽 — 「집으로 돌아감」을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C5","difficulty":4,"kind":"sa","stem":"『국어』 71쪽 — 「집으로 돌아감」을 뜻하는 낱말을 쓰세요.","answer":["귀가"],"explanation":["집으로 돌아감은 「귀가」예요.","안전 요원의 말에 나와요.","낱말 알기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#9','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','『국어』 73쪽 — 나에게 멋진 날은 어떤 날인지 그 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"『국어』 73쪽 — 나에게 멋진 날은 어떤 날인지 그 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 나에게 멋진 날은 가족과 바다에 가는 날이에요. 모래성을 쌓으며 놀 수 있으니까요. — 멋진 날과 까닭이 있으면 맞아요.","scoring_points":["나에게 멋진 날을 썼는가","까닭을 썼는가","문장이 자연스러운가"]},"explanation":["기분 좋고 행복했던 때를 떠올려요.","까닭을 「~니까」로 이어 써요.","친구의 멋진 날과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#10','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','산체스 부인의 말을 보고 산체스 부인이 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"산체스 부인의 말을 보고 산체스 부인이 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 산체스 부인은 맑은 날 페인트칠하는 것을 좋아해요. — 산체스 부인이 한 말을 근거로 썼으면 맞아요.","scoring_points":["산체스 부인의 말을 근거로 썼는가","맑은 하늘·페인트칠과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["인물의 생각은 인물이 한 말에서 찾아요.","하늘이 맑아서 페인트칠하기 좋다고 했어요.","말풍선을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#1','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','「닭이 흙을 밟고 넓은 마당을 지나갔어요.」에서 겹받침이 있는 글자는?',ARRAY['K1-2-u2-X01','K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"「닭이 흙을 밟고 넓은 마당을 지나갔어요.」에서 겹받침이 있는 글자는?","options":[{"t":"넓","correct":true},{"t":"갔","mis":"K1-2-u2-X01"},{"t":"마","mis":"K1-2-u2-X02"}],"explanation":["「넓」의 받침은 ㄼ, 겹받침이에요.","「갔」의 ㅆ은 쌍받침, 「마」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#2','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','낱말 카드 — 꼬꼬댁 우는 동물을 바르게 쓴 것은?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":2,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"낱말 카드 — 꼬꼬댁 우는 동물을 바르게 쓴 것은?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K1-2-u2-X04"},{"t":"닦","mis":"K1-2-u2-X05"}],"explanation":["「닭」의 받침은 ㄺ이에요.","소리 나는 대로 쓰거나 다른 받침을 쓰면 안 돼요.","카드에는 낱말을 바르게 써요."],"asset":{"type":"scene","icon":"🐓","text":"꼬꼬댁 우는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#3','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','낱말 카드 — 화분 속에 든 것을 바르게 쓴 것은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":3,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"낱말 카드 — 화분 속에 든 것을 바르게 쓴 것은?","options":[{"t":"흙","correct":true},{"t":"흑","mis":"K1-2-u2-X04"},{"t":"흘","mis":"K1-2-u2-X04"}],"explanation":["「흙」의 받침은 ㄺ이에요.","소리 나는 대로 쓰면 안 돼요.","카드에는 낱말을 바르게 써요."],"asset":{"type":"scene","icon":"🪴","text":"화분 속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#4','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','낱말 카드 — 수 8을 바르게 쓴 것은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":4,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"낱말 카드 — 수 8을 바르게 쓴 것은?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K1-2-u2-X04"},{"t":"여덥","mis":"K1-2-u2-X04"}],"explanation":["「여덟」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","카드에는 낱말을 바르게 써요."],"asset":{"type":"scene","icon":"8️⃣","text":"수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#5','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','겹받침이 있는 글자만 찾아요. 알맞은 것은?',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":5,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"겹받침이 있는 글자만 찾아요. 알맞은 것은?","options":[{"t":"굵","correct":true},{"t":"낚","mis":"K1-2-u2-X01"},{"t":"있","mis":"K1-2-u2-X01"}],"explanation":["「굵」의 받침 ㄺ은 서로 다른 자음자 두 개예요.","낚의 ㄲ, 있의 ㅆ은 같은 자음자가 겹친 쌍받침이에요.","쌍받침은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#6','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','「값」의 받침은 무엇인가요?',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":6,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「값」의 받침은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"홑받침","mis":"K1-2-u2-X01"}],"explanation":["「값」의 ㅄ은 서로 다른 자음자 두 개로 된 겹받침이에요.","같은 자음자가 겹치면 쌍받침, 하나면 홑받침이에요.","ㅂ과 ㅅ은 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#7','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','「밖」의 받침은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X02']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「밖」의 받침은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"홑받침","mis":"K1-2-u2-X02"}],"explanation":["같은 자음자 ㄱ이 겹친 ㄲ은 쌍받침이에요.","서로 다른 자음자 두 개라야 겹받침이에요.","ㄱ과 ㄱ은 같은 자음자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#8','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','겹받침 낱말 카드에 꼭 들어가야 하는 것은?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":8,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"겹받침 낱말 카드에 꼭 들어가야 하는 것은?","options":[{"t":"겹받침이 있는 낱말과 그 낱말을 나타내는 그림","correct":true},{"t":"여러 가지 색깔 무늬만","mis":"K1-2-u2-X15"},{"t":"숫자만","mis":"K1-2-u2-X15"}],"explanation":["낱말과 그림이 함께 들어가요.","그림보다 낱말을 바르게 쓰는 것이 더 중요해요.","카드를 만드는 까닭을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#9','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'match','auto','그림과 카드에 넣을 겹받침 낱말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":2,"kind":"match","stem":"그림과 카드에 넣을 겹받침 낱말을 이어 보세요.","pairs":[{"l":"🐓 꼬꼬댁 우는 동물","r":"닭"},{"l":"🪴 화분 속","r":"흙"},{"l":"8️⃣ 수","r":"여덟"},{"l":"📖 책을","r":"읽다"}],"mis":"K1-2-u2-X04","explanation":["닭·흙은 ㄺ, 여덟은 ㄼ이에요.","읽다도 ㄺ이에요.","낱말을 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#10','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',3,'mc','auto','「겹받침을 찾아라」 놀이에서 찾은 글자는 어떻게 하나요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":10,"concept":"K1-2-u2-C6","difficulty":3,"kind":"mc","stem":"「겹받침을 찾아라」 놀이에서 찾은 글자는 어떻게 하나요?","options":[{"t":"소리 내어 바르게 읽어요","correct":true},{"t":"찾은 글자를 지워요","mis":"K1-2-u2-X15"},{"t":"글자 옆에 그림만 그려요","mis":"K1-2-u2-X15"}],"explanation":["찾은 글자를 바르게 읽는 것이 중요해요.","지우거나 그림만 그리면 배운 것을 쓰지 못해요.","놀이의 목적을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#1','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',2,'mc','auto','「짧 · 밖 · 있」 가운데 겹받침이 있는 글자는?',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「짧 · 밖 · 있」 가운데 겹받침이 있는 글자는?","options":[{"t":"짧","correct":true},{"t":"밖","mis":"K1-2-u2-X01"},{"t":"있","mis":"K1-2-u2-X01"}],"explanation":["「짧」의 받침 ㄼ은 겹받침이에요.","밖·있은 쌍받침이에요.","같은 자음자인지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#2','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',2,'mc','auto','「끓 · 낚 · 강」 가운데 겹받침이 있는 글자는?',ARRAY['K1-2-u2-X01','K1-2-u2-X02']::text[],false,'{"seq":2,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「끓 · 낚 · 강」 가운데 겹받침이 있는 글자는?","options":[{"t":"끓","correct":true},{"t":"낚","mis":"K1-2-u2-X01"},{"t":"강","mis":"K1-2-u2-X02"}],"explanation":["「끓」의 받침 ㅀ은 겹받침이에요.","낚은 쌍받침, 강은 받침이 하나예요.","받침 자리의 자음자를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
