INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#4','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'error','auto','친구가 낱말 카드에 「여덜」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":4,"concept":"K1-2-u2-C6","difficulty":3,"kind":"error","stem":"친구가 낱말 카드에 「여덜」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소리 나는 대로 썼어요 — 「여덟」으로 써야 해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「여덜」이 맞아요","mis":"K1-2-u2-X04"},{"t":"「여덥」으로 써야 해요","mis":"K1-2-u2-X05"}],"explanation":["「여덟」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","『국어』 74~75쪽 카드 예시를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#5','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'error','auto','친구가 카드에 그림만 크게 그리고 낱말은 「흑」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":5,"concept":"K1-2-u2-C6","difficulty":3,"kind":"error","stem":"친구가 카드에 그림만 크게 그리고 낱말은 「흑」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"낱말을 바르게 쓰는 것이 더 중요해요 — 「흙」으로 고쳐요","correct":true,"mis_target":"K1-2-u2-X15"},{"t":"그림을 더 크게 그려야 해요","mis":"K1-2-u2-X15"},{"t":"잘 만들었어요","mis":"K1-2-u2-X15"}],"explanation":["카드 만들기는 겹받침을 아는 것이 목적이에요.","그림에만 힘쓰면 안 돼요.","낱말부터 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#6','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'match','auto','글자와 받침의 종류를 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C6","difficulty":3,"kind":"match","stem":"글자와 받침의 종류를 이어 보세요.","pairs":[{"l":"값","r":"겹받침"},{"l":"밖","r":"쌍받침"},{"l":"강","r":"홑받침"}],"mis":"K1-2-u2-X01","explanation":["값의 ㅄ은 겹받침, 밖의 ㄲ은 쌍받침이에요.","강의 ㅇ은 자음자 하나인 홑받침이에요.","받침 자리의 자음자를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#7','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'ox','auto','「갔」의 받침 ㅆ은 겹받침이에요.',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"「갔」의 받침 ㅆ은 겹받침이에요.","answer":"X","reason_options":[{"t":"ㅆ은 같은 자음자 ㅅ이 겹친 쌍받침이니까","correct":true},{"t":"자음자가 두 개면 모두 겹받침이니까","mis":"K1-2-u2-X01"}],"mis":"K1-2-u2-X01","explanation":["같은 자음자가 겹치면 쌍받침이에요.","서로 다른 자음자 두 개라야 겹받침이에요.","ㅅ과 ㅅ은 같은 자음자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#8','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'sa','auto','꼬꼬댁 우는 동물을 겹받침에 주의하여 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u2-C6","difficulty":4,"kind":"sa","stem":"꼬꼬댁 우는 동물을 겹받침에 주의하여 쓰세요.","answer":["닭"],"explanation":["「닭」이에요. 받침은 ㄺ이에요.","「닥」은 소리 나는 대로 쓴 것이에요.","카드에 쓰듯 바르게 써요."],"asset":{"type":"scene","icon":"🐓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#9','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'sa','auto','수 8을 글자로 바르게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":4,"kind":"sa","stem":"수 8을 글자로 바르게 쓰세요.","answer":["여덟"],"explanation":["「여덟」이에요. 받침은 ㄼ이에요.","「여덜」은 소리 나는 대로 쓴 것이에요.","카드에 쓰듯 바르게 써요."],"asset":{"type":"scene","icon":"8️⃣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#10','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'essay','teacher','책이나 교실 둘레에서 겹받침 낱말을 두 개 찾아 쓰고, 각각 받침을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C6","difficulty":4,"kind":"essay","stem":"책이나 교실 둘레에서 겹받침 낱말을 두 개 찾아 쓰고, 각각 받침을 쓰세요.","answer_guide":{"answer":"예: 흙 — ㄺ / 넓다 — ㄼ / 앉다 — ㄵ — 겹받침 낱말을 바르게 쓰고 받침을 맞게 쓰면 맞아요.","scoring_points":["겹받침 낱말을 두 개 썼는가","낱말을 바르게 썼는가","받침을 맞게 썼는가"]},"explanation":["서로 다른 자음자 두 개로 된 받침을 찾아요.","쌍받침 낱말(밖·있다)은 빼요.","찾은 낱말을 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#1','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',1,'mc','auto','받침에 서로 다른 자음자 두 개가 있는 글자는?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"받침에 서로 다른 자음자 두 개가 있는 글자는?","options":[{"t":"밟","correct":true},{"t":"어","mis":"K1-2-u2-X02"},{"t":"운","mis":"K1-2-u2-X02"}],"explanation":["「밟」의 받침은 ㄼ이에요.","어는 받침이 없고 운은 ㄴ 하나예요.","『국어』 38쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#2','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',1,'mc','auto','「낚다」의 받침 ㄲ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「낚다」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"모음자","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㄱ이 겹친 쌍받침이에요.","서로 다른 자음자 두 개가 겹받침이에요.","『국어』 39쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#3','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',1,'mc','auto','환한 전등 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"환한 전등 그림에 어울리는 문장은?","options":[{"t":"불빛이 밝다.","correct":true},{"t":"불빛이 밝따.","mis":"K1-2-u2-X04"},{"t":"불빛이 발따.","mis":"K1-2-u2-X04"}],"explanation":["[박따]로 소리 나도 「밝다」로 써요.","소리 나는 대로 쓰면 안 돼요.","『국어』 46쪽이에요."],"asset":{"type":"scene","icon":"💡"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#4','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',1,'mc','auto','『국어』 78쪽 — 「까마귀」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 — 「까마귀」를 바르게 읽은 것은?","options":[{"t":"[까마귀]","correct":true},{"t":"[까마기]","mis":"K1-2-u2-X09"},{"t":"[까마구]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 했다가 펴며 읽어요.","[까마기]·[까마구]는 ㅟ를 잘못 읽은 것이에요.","거울을 보며 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#5','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',1,'mc','auto','『국어』 77쪽 편지의 글쓴이는 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 77쪽 편지의 글쓴이는 누구인가요?","options":[{"t":"민혁","correct":true},{"t":"준호","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["편지 끝에 「민혁이가」라고 쓰여 있어요.","준호는 편지를 받는 사람이에요.","편지의 끝을 봐요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#6','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',1,'mc','auto','에마 누나가 생각하는 멋진 날은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"에마 누나가 생각하는 멋진 날은?","options":[{"t":"바람이 씽씽 불어서 연 날리기 좋은 날","correct":true},{"t":"하늘이 맑아서 페인트칠하기 좋은 날","mis":"K1-2-u2-X13"},{"t":"모두들 안전하게 귀가하는 날","mis":"K1-2-u2-X13"}],"explanation":["에마 누나는 연 날리기 좋은 날이라고 했어요.","다른 인물의 말과 헷갈리지 않아요.","말풍선의 이름을 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#7','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C6',1,'mc','auto','꼬꼬댁 우는 동물을 바르게 쓴 것은?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"꼬꼬댁 우는 동물을 바르게 쓴 것은?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K1-2-u2-X04"},{"t":"닦","mis":"K1-2-u2-X05"}],"explanation":["「닭」의 받침은 ㄺ이에요.","소리 나는 대로 쓰면 안 돼요.","『국어』 74~75쪽 낱말 카드예요."],"asset":{"type":"scene","icon":"🐓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#8','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',1,'mc','auto','『국어』 76쪽 — 바르게 쓴 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 76쪽 — 바르게 쓴 문장은?","options":[{"t":"흙 속에 들어가다.","correct":true},{"t":"흑 속에 들어가다.","mis":"K1-2-u2-X04"},{"t":"흘 속에 들어가다.","mis":"K1-2-u2-X04"}],"explanation":["[흑쏘게]로 소리 나도 「흙」으로 써요.","소리 나는 대로 쓰면 안 돼요.","받침을 낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
