INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#10','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',2,'match','auto','글자와 받침의 자음자를 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"글자와 받침의 자음자를 이어 보세요.","pairs":[{"l":"밟","r":"ㄹ과 ㅂ"},{"l":"싫","r":"ㄹ과 ㅎ"},{"l":"값","r":"ㅂ과 ㅅ"}],"mis":"K1-2-u2-X03","explanation":["밟은 ㄼ, 싫은 ㅀ이에요.","값은 ㅄ이에요.","『국어』 39쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#11','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',2,'mc','auto','「닥과 병아리가 모이를 먹는다.」를 바르게 고치면?',ARRAY['K1-2-u2-X05','K1-2-u2-X04']::text[],false,'{"seq":11,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「닥과 병아리가 모이를 먹는다.」를 바르게 고치면?","options":[{"t":"닭과 병아리가 모이를 먹는다.","correct":true},{"t":"닦과 병아리가 모이를 먹는다.","mis":"K1-2-u2-X05"},{"t":"닥과 병아리가 모이를 먹는다.","mis":"K1-2-u2-X04"}],"explanation":["「닭」의 받침은 ㄺ이에요.","소리 나는 대로 쓰거나 다른 받침을 쓰면 안 돼요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
