INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#13','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',2,'mc','auto','「흙이 어디 있는지 아세요?」에서 「흙이」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":13,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「흙이 어디 있는지 아세요?」에서 「흙이」를 바르게 읽은 것은?","options":[{"t":"[흘기]","correct":true},{"t":"[흐기]","mis":"K1-2-u2-X08"},{"t":"[흑이]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 와서 ㄱ이 넘어가 [흘기]예요.","받침을 빼먹거나 끊어 읽으면 안 돼요.","『국어』 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#14','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',2,'mc','auto','『국어』 77쪽 — 민혁이가 준호에게 하고 싶은 말은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":14,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 77쪽 — 민혁이가 준호에게 하고 싶은 말은?","options":[{"t":"넘어졌을 때 도와줘서 고맙다","correct":true},{"t":"같이 달리기를 하자","mis":"K1-2-u2-X11"},{"t":"넘어져서 부끄러웠다","mis":"K1-2-u2-X11"}],"explanation":["「준호야, 정말 고마워.」에 하고 싶은 말이 있어요.","부끄러웠던 것은 있었던 일이에요.","「고마워」를 찾아봐요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#15','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',2,'match','auto','『국어』 71쪽 — 낱말과 그 뜻을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"『국어』 71쪽 — 낱말과 그 뜻을 이어 보세요.","pairs":[{"l":"요원","r":"어떤 일을 하는 데 꼭 필요한 사람."},{"l":"귀가","r":"집으로 돌아감."},{"l":"건널목","r":"길을 건널 수 있게 정해진 곳."}],"mis":"K1-2-u2-X16","explanation":["요원은 꼭 필요한 사람, 귀가는 집으로 돌아감이에요.","건널목은 길을 건널 수 있게 정해진 곳이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#16','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',2,'mc','auto','『국어』 78쪽 — 「주사위를 던져서」의 「주사위」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":16,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 78쪽 — 「주사위를 던져서」의 「주사위」를 바르게 읽은 것은?","options":[{"t":"[주사위]","correct":true},{"t":"[주사이]","mis":"K1-2-u2-X09"},{"t":"[주사우]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ를 살려 [주사위]로 읽어요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","입술을 동그랗게 했다가 펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
