INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#18','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',3,'error','auto','「닥과 병아리가 모이를 먹는다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「닥과 병아리가 모이를 먹는다.」 무엇이 잘못되었나요?","options":[{"t":"「닥」을 「닭」으로 고쳐야 해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「모이」를 고쳐야 해요","mis":"K1-2-u2-X06"},{"t":"맞게 쓴 문장이에요","mis":"K1-2-u2-X04"}],"explanation":["「닭」의 받침은 ㄺ이에요.","소리 나는 대로 쓰면 안 돼요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#19','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',3,'error','auto','친구가 「흙이」를 [흐기]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「흙이」를 [흐기]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 모음이 와서 [흘기]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X08"},{"t":"[흙이]로 끊어 읽어야 해요","mis":"K1-2-u2-X08"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X08"}],"explanation":["겹받침 뒤에 모음이 오면 둘 다 소리 나요.","ㄹ을 빼먹으면 안 돼요.","『국어』 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#20','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',3,'error','auto','「민혁이가 하고 싶은 말은 ‘넘어져서 부끄러웠어’예요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X11','K1-2-u2-X12']::text[],false,'{"seq":20,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"「민혁이가 하고 싶은 말은 ‘넘어져서 부끄러웠어’예요.」 무엇이 잘못되었나요?","options":[{"t":"그것은 있었던 일이에요 — 하고 싶은 말은 「도와줘서 고마워」예요","correct":true,"mis_target":"K1-2-u2-X11"},{"t":"맞게 말했어요","mis":"K1-2-u2-X11"},{"t":"글쓴이는 준호예요","mis":"K1-2-u2-X12"}],"explanation":["부끄러웠던 것은 있었던 일이에요.","민혁이는 고맙다는 말을 하려고 편지를 썼어요.","「정말 고마워」를 찾아봐요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#21','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',3,'ox','auto','다니엘의 이웃들은 같은 물음에 저마다 다른 멋진 날을 말했어요.',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":21,"concept":"K1-2-u2-C5","difficulty":3,"kind":"ox","stem":"다니엘의 이웃들은 같은 물음에 저마다 다른 멋진 날을 말했어요.","answer":"O","reason_options":[{"t":"인물마다 좋아하고 중요하게 여기는 것이 다르니까","correct":true},{"t":"물음이 하나면 답도 하나뿐이니까","mis":"K1-2-u2-X14"}],"mis":"K1-2-u2-X14","explanation":["질문은 하나여도 대답은 여러 가지일 수 있어요.","다른 생각은 틀린 것이 아니에요.","『국어』 72쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
