INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#23','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',4,'sa','auto','「필통에 연필이 업다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"「필통에 연필이 업다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.","answer":["없다"],"explanation":["필통에 연필이 「없다」예요.","받침은 ㅄ이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#24','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',4,'essay','teacher','『국어』 77쪽 — 민혁이가 준호에게 하고 싶은 말을 까닭과 함께 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어』 77쪽 — 민혁이가 준호에게 하고 싶은 말을 까닭과 함께 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 넘어졌을 때 다가와 일으켜 주어서 정말 고마워. — 고마운 마음과 그 까닭이 있으면 맞아요.","scoring_points":["고마운 마음이 들어 있는가","까닭(일으켜 주었다)을 썼는가","있었던 일만 옮기지 않았는가"]},"explanation":["「정말 고마워」가 하고 싶은 말이에요.","넘어졌을 때 도와준 것이 까닭이에요.","둘을 이어 써요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#25','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',4,'essay','teacher','에마 누나의 말을 보고 에마 누나가 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"에마 누나의 말을 보고 에마 누나가 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 에마 누나는 바람 부는 날 연 날리는 것을 좋아해요. — 에마 누나의 말을 근거로 썼으면 맞아요.","scoring_points":["에마 누나의 말을 근거로 썼는가","연 날리기와 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["인물의 생각은 인물이 한 말에서 찾아요.","바람이 씽씽 불어서 연 날리기 좋다고 했어요.","말풍선을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#1','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',1,'mc','auto','받침에 서로 다른 자음자 두 개가 있는 글자는?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"받침에 서로 다른 자음자 두 개가 있는 글자는?","options":[{"t":"싫","correct":true},{"t":"즐","mis":"K1-2-u2-X02"},{"t":"어","mis":"K1-2-u2-X02"}],"explanation":["「싫」의 받침은 ㅀ이에요.","즐은 ㄹ 하나, 어는 받침이 없어요.","『국어』 38쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#2','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',1,'mc','auto','「밟다」의 받침 ㄼ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「밟다」의 받침 ㄼ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"모음자","mis":"K1-2-u2-X03"}],"explanation":["서로 다른 자음자 ㄹ과 ㅂ으로 된 겹받침이에요.","같은 자음자가 겹친 것이 쌍받침이에요.","『국어』 39쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#3','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',1,'mc','auto','넓은 들판 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"넓은 들판 그림에 어울리는 문장은?","options":[{"t":"들판이 넓다.","correct":true},{"t":"들판이 널따.","mis":"K1-2-u2-X04"},{"t":"들판이 넙다.","mis":"K1-2-u2-X04"}],"explanation":["[널따]로 소리 나도 「넓다」로 써요.","소리 나는 대로 쓰면 안 돼요.","『국어』 46쪽이에요."],"asset":{"type":"scene","icon":"🌾"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#4','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',1,'mc','auto','『국어』 78쪽 — 「다람쥐」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 — 「다람쥐」를 바르게 읽은 것은?","options":[{"t":"[다람쥐]","correct":true},{"t":"[다람지]","mis":"K1-2-u2-X09"},{"t":"[다람주]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ를 또박또박 읽어 [다람쥐]예요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","입술 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#5','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',1,'mc','auto','『국어』 77쪽 편지를 받는 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 77쪽 편지를 받는 사람은 누구인가요?","options":[{"t":"준호","correct":true},{"t":"민혁","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["「준호야, 안녕?」으로 시작해요.","민혁이는 편지를 쓴 글쓴이예요.","편지의 처음을 봐요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#6','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',1,'mc','auto','산체스 부인이 생각하는 멋진 날은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"산체스 부인이 생각하는 멋진 날은?","options":[{"t":"하늘이 맑아서 페인트칠하기 좋은 날","correct":true},{"t":"바람이 씽씽 불어서 연 날리기 좋은 날","mis":"K1-2-u2-X13"},{"t":"모두들 안전하게 귀가하는 날","mis":"K1-2-u2-X13"}],"explanation":["산체스 부인은 페인트칠하기 좋은 날이라고 했어요.","다른 인물의 말과 헷갈리지 않아요.","말풍선의 이름을 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
