INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#11','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',2,'mc','auto','「크레파스의 길이가 연필의 길이보다 짭다.」의 「짭다」를 바르게 고치면?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":11,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「크레파스의 길이가 연필의 길이보다 짭다.」의 「짭다」를 바르게 고치면?","options":[{"t":"짧다","correct":true},{"t":"짤다","mis":"K1-2-u2-X04"},{"t":"짭다","mis":"K1-2-u2-X04"}],"explanation":["「짧다」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
