INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#13','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',2,'mc','auto','「흙 속에 들어가서」에서 「흙 속에」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":13,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「흙 속에 들어가서」에서 「흙 속에」를 바르게 읽은 것은?","options":[{"t":"[흑쏘게]","correct":true},{"t":"[흘쏘게]","mis":"K1-2-u2-X07"},{"t":"[흐쏘게]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 자음이 와서 ㄱ만 소리 나 [흑쏘게]예요.","ㄹ로 읽거나 받침을 빼먹으면 안 돼요.","『국어』 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#14','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',2,'mc','auto','「사용한 물건을 제자리에 두자」의 글쓴이가 하고 싶은 말은?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":14,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「사용한 물건을 제자리에 두자」의 글쓴이가 하고 싶은 말은?","options":[{"t":"물건을 쓰고 나서 제자리에 두자","correct":true},{"t":"동생과 사이좋게 지내자","mis":"K1-2-u2-X11"},{"t":"풀과 가위를 새로 사자","mis":"K1-2-u2-X11"}],"explanation":["제목에 하고 싶은 말이 나타나 있어요.","동생 이야기는 있었던 일이에요.","제목을 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#15','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',2,'match','auto','『국어』 60쪽 — 낱말과 그 뜻을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u2-C3","difficulty":2,"kind":"match","stem":"『국어』 60쪽 — 낱말과 그 뜻을 이어 보세요.","pairs":[{"l":"간신히","r":"겨우. 매우 힘들게."},{"l":"하마터면","r":"조금만 잘못했더라면."},{"l":"무시무시하다","r":"아주 많이 무섭다."}],"mis":"K1-2-u2-X16","explanation":["간신히는 겨우, 하마터면은 조금만 잘못했더라면이에요.","무시무시하다는 아주 많이 무섭다예요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
