INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#18','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',3,'error','auto','「크레파스가 연필보다 짭다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「크레파스가 연필보다 짭다.」 무엇이 잘못되었나요?","options":[{"t":"「짭다」를 「짧다」로 고쳐야 해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「연필」을 고쳐야 해요","mis":"K1-2-u2-X06"},{"t":"맞게 쓴 문장이에요","mis":"K1-2-u2-X04"}],"explanation":["「짧다」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#19','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',3,'error','auto','친구가 「흙 속에」를 [흘쏘게]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「흙 속에」를 [흘쏘게]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 자음이 와서 ㄱ만 소리 나 [흑쏘게]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X07"},{"t":"둘 다 소리 내야 해요","mis":"K1-2-u2-X07"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X07"}],"explanation":["겹받침 뒤에 자음이 오면 하나만 소리 나요.","「흙」은 이때 ㄱ이 소리 나요.","『국어』 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#20','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',3,'error','auto','「이 편지의 글쓴이는 준호예요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":20,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"「이 편지의 글쓴이는 준호예요.」 무엇이 잘못되었나요?","options":[{"t":"준호는 편지를 받는 사람이에요 — 글쓴이는 민혁이에요","correct":true,"mis_target":"K1-2-u2-X12"},{"t":"글쓴이는 선생님이에요","mis":"K1-2-u2-X12"},{"t":"맞게 말했어요","mis":"K1-2-u2-X12"}],"explanation":["편지 끝의 「민혁이가」가 글쓴이예요.","「준호야」는 받는 사람을 부르는 말이에요.","편지의 처음과 끝을 봐요."],"asset":{"type":"passage","lines":["준호야, 안녕? 지난번에 내가 넘어졌을 때 기억나?","그때 나는 발도 아프고 친구들도 쳐다봐서 많이 부끄러웠어.","그런데 네가 다가와서 괜찮냐고 물어보고 일으켜 주었어.","준호야, 정말 고마워.","다음에 네가 힘든 일이 있을 때 내가 꼭 도와줄게.","민혁이가"],"title":"국어 77쪽 — 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#21','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',3,'error','auto','「안전 요원의 멋진 날은 에마 누나와 다르니까 틀렸어요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":21,"concept":"K1-2-u2-C5","difficulty":3,"kind":"error","stem":"「안전 요원의 멋진 날은 에마 누나와 다르니까 틀렸어요.」 무엇이 잘못되었나요?","options":[{"t":"생각은 사람마다 다를 수 있어요 — 틀린 것이 아니에요","correct":true,"mis_target":"K1-2-u2-X14"},{"t":"맞게 말했어요","mis":"K1-2-u2-X14"},{"t":"안전 요원은 말을 하지 않았어요","mis":"K1-2-u2-X13"}],"explanation":["같은 물음에 다른 대답이 나올 수 있어요.","다른 생각을 존중해요.","『국어』 73쪽이에요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
