INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#23','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',4,'sa','auto','「닥과 병아리가 모이를 먹는다.」에서 잘못 쓴 글자를 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"「닥과 병아리가 모이를 먹는다.」에서 잘못 쓴 글자를 바르게 고쳐 쓰세요.","answer":["닭"],"explanation":["「닭」이에요.","받침은 ㄺ이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#24','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',4,'essay','teacher','「사용한 물건을 제자리에 두자」의 하고 싶은 말을 까닭과 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「사용한 물건을 제자리에 두자」의 하고 싶은 말을 까닭과 이어 쓰세요.","answer_guide":{"answer":"예: 물건을 쉽고 빠르게 찾을 수 있게 쓰고 나서 제자리에 두자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「제자리에 두자」가 있는가","까닭을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","끝 줄이 까닭이에요.","둘을 이어 써요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#25','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',4,'essay','teacher','산체스 부인의 말을 보고 산체스 부인이 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"산체스 부인의 말을 보고 산체스 부인이 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 산체스 부인은 맑은 날 페인트칠하는 것을 좋아해요. — 산체스 부인의 말을 근거로 썼으면 맞아요.","scoring_points":["산체스 부인의 말을 근거로 썼는가","맑은 하늘·페인트칠과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["인물의 생각은 인물이 한 말에서 찾아요.","하늘이 맑아서 페인트칠하기 좋다고 했어요.","말풍선을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#1','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',1,'mc','auto','받침에 서로 다른 자음자 두 개가 있는 글자는?',ARRAY['K1-2-u2-X02','K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"받침에 서로 다른 자음자 두 개가 있는 글자는?","options":[{"t":"흙","correct":true},{"t":"운","mis":"K1-2-u2-X02"},{"t":"썩","mis":"K1-2-u2-X03"}],"explanation":["「흙」의 받침은 ㄺ이에요.","운은 ㄴ 하나, 썩은 ㄱ 하나예요(ㅆ은 첫소리).","받침 자리만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#2','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',1,'mc','auto','「밖」의 받침 ㄲ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「밖」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㄱ이 겹친 쌍받침이에요.","겹받침은 서로 다른 자음자 두 개예요.","『국어』 75쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#3','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',1,'mc','auto','아파서 누운 아이 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"아파서 누운 아이 그림에 어울리는 문장은?","options":[{"t":"감기를 앓다.","correct":true},{"t":"감기를 알타.","mis":"K1-2-u2-X04"},{"t":"감기를 알다.","mis":"K1-2-u2-X06"}],"explanation":["아파서 누웠으니 「앓다」예요.","「알다」는 무엇을 안다는 뜻의 다른 낱말이에요.","『국어』 46쪽이에요."],"asset":{"type":"scene","icon":"🤒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#4','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',1,'mc','auto','『국어』 78쪽 — 「가위바위보」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 — 「가위바위보」를 바르게 읽은 것은?","options":[{"t":"[가위바위보]","correct":true},{"t":"[가이바이보]","mis":"K1-2-u2-X09"},{"t":"[가우바우보]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ를 살려 [가위바위보]로 읽어요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","입술 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#5','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',1,'mc','auto','「사용한 물건을 제자리에 두자」의 글쓴이는?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「사용한 물건을 제자리에 두자」의 글쓴이는?","options":[{"t":"김서연","correct":true},{"t":"서연이 동생","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["글 끝에 「1학년 김서연」이라고 쓰여 있어요.","동생은 글에 나오는 사람이에요.","글의 끝을 봐요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#6','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',1,'mc','auto','안전 요원이 생각하는 멋진 날은?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"안전 요원이 생각하는 멋진 날은?","options":[{"t":"모두들 안전하게 귀가하는 날","correct":true},{"t":"하늘이 맑아서 페인트칠하기 좋은 날","mis":"K1-2-u2-X13"},{"t":"바람이 씽씽 불어서 연 날리기 좋은 날","mis":"K1-2-u2-X13"}],"explanation":["안전 요원은 모두 안전하게 귀가하는 날이라고 했어요.","다른 인물의 말과 헷갈리지 않아요.","말풍선의 이름을 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
