INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#11','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',2,'mc','auto','「연필심이 달았다.」의 「달았다」를 바르게 고치면?',ARRAY['K1-2-u2-X05','K1-2-u2-X06']::text[],false,'{"seq":11,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「연필심이 달았다.」의 「달았다」를 바르게 고치면?","options":[{"t":"닳았다","correct":true},{"t":"닭았다","mis":"K1-2-u2-X05"},{"t":"달았다","mis":"K1-2-u2-X06"}],"explanation":["써서 줄어든 것이니 「닳았다」예요.","「달았다」는 맛이 달다는 뜻으로 들려요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
