INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#13','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',2,'mc','auto','「흙을 밟다.」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],false,'{"seq":13,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「흙을 밟다.」를 바르게 읽은 것은?","options":[{"t":"[흘글 밥ː따]","correct":true},{"t":"[흐글 밥따]","mis":"K1-2-u2-X08"},{"t":"[흘글 발브따]","mis":"K1-2-u2-X07"}],"explanation":["흙을은 [흘글], 밟다는 [밥ː따]예요.","받침을 빼먹거나 둘 다 소리 내면 안 돼요.","『국어』 45쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#14','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',2,'mc','auto','「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말은?',ARRAY['K1-2-u2-X11','K1-2-u2-X10']::text[],false,'{"seq":14,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「자전거를 안전하게 타자」의 글쓴이가 하고 싶은 말은?","options":[{"t":"자전거를 안전하게 타자","correct":true},{"t":"새 자전거를 사자","mis":"K1-2-u2-X11"},{"t":"환경 오염을 줄이자","mis":"K1-2-u2-X10"}],"explanation":["제목과 마지막 문장에 하고 싶은 말이 있어요.","환경 이야기는 첫 문장에 나온 좋은 점이에요.","첫 문장만 보지 말아요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
