INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#16','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',2,'mc','auto','「ㅟ」를 바르게 소리 내는 방법은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":16,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「ㅟ」를 바르게 소리 내는 방법은?","options":[{"t":"입술을 동그랗게 했다가 펴며 읽어요","correct":true},{"t":"입을 옆으로 벌린 채 읽어요","mis":"K1-2-u2-X09"},{"t":"입술을 동그랗게 모은 채로만 읽어요","mis":"K1-2-u2-X09"}],"explanation":["ㅜ처럼 동그랗게 했다가 ㅣ처럼 펴요.","한 모양으로만 읽으면 ㅣ나 ㅜ가 돼요.","거울을 보며 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
