INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#18','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',3,'error','auto','「연필심이 달았다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X06','K1-2-u2-X05']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「연필심이 달았다.」 무엇이 잘못되었나요?","options":[{"t":"「달았다」를 「닳았다」로 고쳐야 해요","correct":true,"mis_target":"K1-2-u2-X06"},{"t":"「닭았다」로 고쳐야 해요","mis":"K1-2-u2-X05"},{"t":"맞게 쓴 문장이에요","mis":"K1-2-u2-X06"}],"explanation":["써서 줄어든 것은 「닳았다」예요.","「닭」의 받침과 헷갈리면 안 돼요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#19','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',3,'error','auto','친구가 「까마귀」를 [까마기]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「까마귀」를 [까마기]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"ㅟ를 ㅣ로 읽었어요 — [까마귀]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X09"},{"t":"[까마구]로 읽어야 해요","mis":"K1-2-u2-X09"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 했다가 펴며 읽어요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","『국어』 78쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#20','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',3,'error','auto','「서연이 글에서 하고 싶은 말은 첫 문장뿐이에요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X10','K1-2-u2-X12']::text[],false,'{"seq":20,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"「서연이 글에서 하고 싶은 말은 첫 문장뿐이에요.」 무엇이 잘못되었나요?","options":[{"t":"첫 문장만 보았어요 — 제목과 쓴 까닭을 이어 「제자리에 두자」를 찾아요","correct":true,"mis_target":"K1-2-u2-X10"},{"t":"맞게 말했어요","mis":"K1-2-u2-X10"},{"t":"글쓴이는 동생이에요","mis":"K1-2-u2-X12"}],"explanation":["첫 문장은 서연이의 습관이에요.","끝까지 읽고 제목과 이어야 해요.","『국어』 64쪽 방법이에요."],"asset":{"type":"passage","lines":["나는 물건을 쓰고 나서 제자리에 둡니다.","그렇게 하면 다음에 그 물건을 쓰려고 할 때 빨리 찾을 수 있습니다.","하지만 내 동생은 풀이나 가위와 같은 물건을 쓰고 나서 아무 데나 둡니다.","그래서 다음에 쓰려면 한참을 찾아야 합니다.","물건을 쓰고 나서 제자리에 둡시다.","그렇게 해야 물건을 쉽고 빠르게 찾을 수 있습니다.","1학년 김서연"],"title":"사용한 물건을 제자리에 두자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#21','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',3,'error','auto','「산체스 부인의 멋진 날은 연 날리기 좋은 날이에요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X13','K1-2-u2-X14']::text[],false,'{"seq":21,"concept":"K1-2-u2-C5","difficulty":3,"kind":"error","stem":"「산체스 부인의 멋진 날은 연 날리기 좋은 날이에요.」 무엇이 잘못되었나요?","options":[{"t":"그것은 에마 누나의 말이에요 — 산체스 부인은 페인트칠하기 좋은 날이에요","correct":true,"mis_target":"K1-2-u2-X13"},{"t":"맞게 말했어요","mis":"K1-2-u2-X13"},{"t":"산체스 부인은 멋진 날이 없어요","mis":"K1-2-u2-X14"}],"explanation":["인물마다 한 말을 나누어 살펴봐요.","말한 사람을 헷갈리면 생각도 헷갈려요.","말풍선의 이름을 봐요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#22','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C6',3,'error','auto','친구가 낱말 카드에 「여덜」이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"error","stem":"친구가 낱말 카드에 「여덜」이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소리 나는 대로 썼어요 — 「여덟」으로 써야 해요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「여덥」으로 써야 해요","mis":"K1-2-u2-X05"},{"t":"맞게 썼어요","mis":"K1-2-u2-X04"}],"explanation":["「여덟」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","카드에는 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#23','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',4,'sa','auto','「크레파스가 연필보다 짭다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"「크레파스가 연필보다 짭다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.","answer":["짧다"],"explanation":["「짧다」예요.","받침은 ㄼ이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#24','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',4,'essay','teacher','「자전거를 안전하게 타자」의 하고 싶은 말을 까닭과 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「자전거를 안전하게 타자」의 하고 싶은 말을 까닭과 이어 쓰세요.","answer_guide":{"answer":"예: 다치지 않게 안전모를 쓰고 신호등을 지키며 자전거를 안전하게 타자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「안전하게 타자」가 있는가","까닭(다치지 않게)을 이었는가","글의 내용과 맞는가"]},"explanation":["제목이 하고 싶은 말이에요.","안전하게 타지 않으면 다칠 수 있어요.","제목과 끝 문장을 이어요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#25','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',4,'essay','teacher','안전 요원의 말을 보고 안전 요원이 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"안전 요원의 말을 보고 안전 요원이 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 안전 요원은 사람들이 다치지 않고 안전하게 집에 가는 것을 중요하게 여겨요. — 안전 요원의 말을 근거로 썼으면 맞아요.","scoring_points":["안전 요원의 말을 근거로 썼는가","안전한 귀가와 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["인물의 생각은 인물이 한 말에서 찾아요.","모두들 안전하게 귀가하는 날이 멋진 날이라고 했어요.","말풍선을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"에마 누나","text":"바람이 씽씽 불어서 연 날리기 좋은 날!"},{"who":"산체스 부인","text":"하늘이 이렇게 맑아서 페인트칠하기 좋은 날이란다."},{"who":"안전 요원","text":"나의 멋진 날은 모두들 안전하게 귀가하는 날."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#1','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',1,'mc','auto','받침에 서로 다른 자음자 두 개가 있는 글자는?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"받침에 서로 다른 자음자 두 개가 있는 글자는?","options":[{"t":"넓","correct":true},{"t":"즐","mis":"K1-2-u2-X02"},{"t":"밭","mis":"K1-2-u2-X02"}],"explanation":["「넓」의 받침은 ㄼ이에요.","즐은 ㄹ, 밭은 ㅌ 하나예요.","받침 자리만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#2','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',1,'mc','auto','「값」의 받침 ㅄ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「값」의 받침 ㅄ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["서로 다른 자음자 ㅂ과 ㅅ으로 된 겹받침이에요.","같은 자음자가 겹친 것이 쌍받침이에요.","『국어』 39쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#3','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',1,'mc','auto','빈 물컵 그림에 어울리는 문장은?',ARRAY['K1-2-u2-X06','K1-2-u2-X04']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"빈 물컵 그림에 어울리는 문장은?","options":[{"t":"물이 없다.","correct":true},{"t":"물이 업다.","mis":"K1-2-u2-X06"},{"t":"물이 업따.","mis":"K1-2-u2-X04"}],"explanation":["물이 비었으니 「없다」예요.","「업다」는 등에 지는 뜻의 다른 낱말이에요.","『국어』 46쪽이에요."],"asset":{"type":"scene","icon":"🥛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#4','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',1,'mc','auto','『국어』 78쪽 — 「널뛰기」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 78쪽 — 「널뛰기」를 바르게 읽은 것은?","options":[{"t":"[널뛰기]","correct":true},{"t":"[널띠기]","mis":"K1-2-u2-X09"},{"t":"[널뚜기]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ를 살려 [널뛰기]로 읽어요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","입술 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#5','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',1,'mc','auto','글을 쓴 사람을 무엇이라고 하나요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"글을 쓴 사람을 무엇이라고 하나요?","options":[{"t":"글쓴이","correct":true},{"t":"제목","mis":"K1-2-u2-X12"},{"t":"인물","mis":"K1-2-u2-X12"}],"explanation":["글을 쓴 사람은 글쓴이예요.","제목은 글의 이름, 인물은 글에 나오는 사람이에요.","『국어』 63쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#6','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',1,'mc','auto','「다니엘의 멋진 날」 — 이웃들이 다니엘에게 하는 인사는?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「다니엘의 멋진 날」 — 이웃들이 다니엘에게 하는 인사는?","options":[{"t":"「멋진 날 보내렴!」","correct":true},{"t":"「잘 가, 다니엘!」","mis":"K1-2-u2-X13"},{"t":"「조심해서 다녀라!」","mis":"K1-2-u2-X13"}],"explanation":["이웃들은 「멋진 날 보내렴!」 하고 인사해요.","다른 인사말은 나오지 않아요.","둘째 줄을 읽어 봐요."],"asset":{"type":"passage","lines":["다니엘은 여러 이웃과 잘 알고 지내요.","할머니 집에 갈 때면 이웃들이 「멋진 날 보내렴!」 하고 인사해요.","다니엘은 이웃들에게 「어떤 날이 멋진 날이에요?」 하고 물어요.","이웃들은 저마다 자기가 생각하는 멋진 날을 말해 줘요."],"title":"다니엘의 멋진 날 (미카 아처 글·그림, 이상희 옮김) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#7','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C6',1,'mc','auto','책을 보며 소리 내는 것을 바르게 쓴 것은?',ARRAY['K1-2-u2-X06','K1-2-u2-X04']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"책을 보며 소리 내는 것을 바르게 쓴 것은?","options":[{"t":"읽다","correct":true},{"t":"익다","mis":"K1-2-u2-X06"},{"t":"일다","mis":"K1-2-u2-X04"}],"explanation":["책을 「읽다」 — 받침은 ㄺ이에요.","「익다」는 음식이 익는다는 뜻의 다른 낱말이에요.","『국어』 74~75쪽 낱말 카드예요."],"asset":{"type":"scene","icon":"📖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#8','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',1,'mc','auto','『국어』 76쪽 — 바르게 쓴 문장은?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 76쪽 — 바르게 쓴 문장은?","options":[{"t":"아주 넓고 위험하거든.","correct":true},{"t":"아주 널고 위험하거든.","mis":"K1-2-u2-X04"},{"t":"아주 널꼬 위험하거든.","mis":"K1-2-u2-X04"}],"explanation":["「넓고」의 받침은 ㄼ이에요.","소리 나는 대로 쓰면 안 돼요.","받침을 낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
