INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#10','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',2,'match','auto','글자와 받침의 자음자를 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"글자와 받침의 자음자를 이어 보세요.","pairs":[{"l":"흙","r":"ㄹ과 ㄱ"},{"l":"닳","r":"ㄹ과 ㅎ"},{"l":"없","r":"ㅂ과 ㅅ"}],"mis":"K1-2-u2-X03","explanation":["흙은 ㄺ, 닳은 ㅀ이에요.","없은 ㅄ이에요.","받침 자리를 왼쪽부터 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#11','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',2,'mc','auto','「필통에 연필이 업다.」의 「업다」를 바르게 고치면?',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":11,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「필통에 연필이 업다.」의 「업다」를 바르게 고치면?","options":[{"t":"없다","correct":true},{"t":"엎다","mis":"K1-2-u2-X06"},{"t":"업다","mis":"K1-2-u2-X06"}],"explanation":["필통에 연필이 「없다」예요.","업다·엎다는 뜻이 다른 낱말이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#12','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',2,'blank','auto','『국어』 47쪽 — 빈칸에 바르게 쓴 것은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#13','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',2,'mc','auto','「개미가 틀림없다.」를 바르게 읽은 것은?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":13,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「개미가 틀림없다.」를 바르게 읽은 것은?","options":[{"t":"[개미가 틀리멉따]","correct":true},{"t":"[개미가 틀리멉스다]","mis":"K1-2-u2-X07"},{"t":"[개미가 틀리머따]","mis":"K1-2-u2-X07"}],"explanation":["「없다」의 ㅄ은 ㅂ만 소리 나 [틀리멉따]예요.","두 소리를 다 내거나 받침을 빼먹으면 안 돼요.","『국어』 45쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#14','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',2,'mc','auto','박물관 게시판의 글쓴이가 하고 싶은 말은?',ARRAY['K1-2-u2-X10','K1-2-u2-X11']::text[],false,'{"seq":14,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"박물관 게시판의 글쓴이가 하고 싶은 말은?","options":[{"t":"박물관을 관람할 때 지킬 일을 지키자","correct":true},{"t":"사진을 많이 찍자","mis":"K1-2-u2-X10"},{"t":"물건을 사 가자","mis":"K1-2-u2-X11"}],"explanation":["세 문장이 모두 지킬 일이에요.","사진을 찍거나 물건을 사라는 말은 없어요.","『국어』 35쪽이에요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
