INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#16','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',2,'ox','auto','「널뛰기」를 [널띠기]로 읽어도 괜찮아요.',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":16,"concept":"K1-2-u2-C3","difficulty":2,"kind":"ox","stem":"「널뛰기」를 [널띠기]로 읽어도 괜찮아요.","answer":"X","reason_options":[{"t":"ㅟ를 살려 [널뛰기]로 읽어야 하니까","correct":true},{"t":"ㅟ와 ㅣ는 같은 소리니까","mis":"K1-2-u2-X09"}],"mis":"K1-2-u2-X09","explanation":["ㅟ를 ㅣ로 읽으면 안 돼요.","입술을 동그랗게 했다가 펴며 읽어요.","『국어』 78쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
