INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#18','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',3,'error','auto','「필통에 연필이 업다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「필통에 연필이 업다.」 무엇이 잘못되었나요?","options":[{"t":"「업다」를 「없다」로 고쳐야 해요","correct":true,"mis_target":"K1-2-u2-X06"},{"t":"「엎다」로 고쳐야 해요","mis":"K1-2-u2-X06"},{"t":"맞게 쓴 문장이에요","mis":"K1-2-u2-X06"}],"explanation":["연필이 없는 것은 「없다」예요.","업다는 등에 지는 것, 엎다는 뒤집는 것이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#19','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',3,'error','auto','친구가 「다람쥐」를 [다람지]로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"친구가 「다람쥐」를 [다람지]로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"ㅟ를 ㅣ로 읽었어요 — [다람쥐]로 읽어야 해요","correct":true,"mis_target":"K1-2-u2-X09"},{"t":"[다람주]로 읽어야 해요","mis":"K1-2-u2-X09"},{"t":"맞게 읽었어요","mis":"K1-2-u2-X09"}],"explanation":["ㅟ를 살려 [다람쥐]로 읽어요.","ㅣ나 ㅜ로만 읽으면 안 돼요.","『국어』 78쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#20','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',3,'error','auto','「자전거 글의 하고 싶은 말은 ‘몸도 건강해진다’예요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X10','K1-2-u2-X12']::text[],false,'{"seq":20,"concept":"K1-2-u2-C4","difficulty":3,"kind":"error","stem":"「자전거 글의 하고 싶은 말은 ‘몸도 건강해진다’예요.」 무엇이 잘못되었나요?","options":[{"t":"첫 문장만 보았어요 — 하고 싶은 말은 「안전하게 타자」예요","correct":true,"mis_target":"K1-2-u2-X10"},{"t":"맞게 말했어요","mis":"K1-2-u2-X10"},{"t":"글쓴이는 자전거예요","mis":"K1-2-u2-X12"}],"explanation":["첫 문장은 자전거를 타면 좋은 점이에요.","제목과 끝 문장에 하고 싶은 말이 있어요.","제목을 봐요."],"asset":{"type":"passage","lines":["자전거를 타면 몸도 건강해지고 환경 오염도 줄일 수 있습니다.","하지만 안전하게 타지 않으면 다칠 수 있습니다.","안전모를 꼭 쓰고, 적당한 속도로 타고, 신호등도 꼭 지켜야 합니다.","우리 모두 자전거를 안전하게 타서 다치지 않으면 좋겠습니다."],"title":"자전거를 안전하게 타자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#21','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',3,'ox','auto','인물의 생각은 인물이 한 말이나 행동을 살펴 알 수 있어요.',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":21,"concept":"K1-2-u2-C5","difficulty":3,"kind":"ox","stem":"인물의 생각은 인물이 한 말이나 행동을 살펴 알 수 있어요.","answer":"O","reason_options":[{"t":"인물이 한 말과 행동에 생각이 드러나니까","correct":true},{"t":"그림의 색깔만 보면 알 수 있으니까","mis":"K1-2-u2-X13"}],"mis":"K1-2-u2-X13","explanation":["인물의 말과 행동을 살펴봐요.","색깔이나 쪽수로는 알 수 없어요.","『국어』 72쪽 알아 두기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#22','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C6',3,'error','auto','친구가 카드에 그림만 크게 그리고 낱말은 「흑」으로 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"error","stem":"친구가 카드에 그림만 크게 그리고 낱말은 「흑」으로 썼어요. 무엇이 잘못되었나요?","options":[{"t":"낱말을 바르게 쓰는 것이 더 중요해요 — 「흙」으로 고쳐요","correct":true,"mis_target":"K1-2-u2-X15"},{"t":"그림을 더 크게 그려야 해요","mis":"K1-2-u2-X15"},{"t":"잘 만들었어요","mis":"K1-2-u2-X15"}],"explanation":["카드 만들기는 겹받침을 아는 것이 목적이에요.","그림에만 힘쓰면 안 돼요.","낱말부터 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#23','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',4,'sa','auto','「연필심이 달았다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"「연필심이 달았다.」에서 잘못 쓴 낱말을 바르게 고쳐 쓰세요.","answer":["닳았다"],"explanation":["「닳았다」예요.","받침은 ㅀ이에요.","『국어』 48쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#24','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',4,'essay','teacher','박물관 게시판의 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"박물관 게시판의 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 박물관을 관람할 때는 사진을 찍지 말고, 떠들지 말고, 물건을 만지지 말자. — 지킬 일이 들어 있으면 맞아요.","scoring_points":["관람할 때 지킬 일이 있는가","세 문장의 뜻을 아울렀는가","문장이 자연스러운가"]},"explanation":["세 문장을 모아 하고 싶은 말로 바꿔요.","한 문장만 옮기면 다 담지 못해요.","『국어』 35쪽이에요."],"asset":{"type":"passage","lines":["사진을 찍지 않습니다.","뛰어다니거나 큰 소리로 떠들지 않습니다.","전시된 물건을 만지지 않습니다."],"title":"국어 35쪽 — 박물관 게시판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#25','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',4,'essay','teacher','『국어』 73쪽 — 나에게 멋진 날은 어떤 날인지 그 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"『국어』 73쪽 — 나에게 멋진 날은 어떤 날인지 그 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 나에게 멋진 날은 친구와 놀이터에서 노는 날이에요. 함께 웃을 수 있으니까요. — 멋진 날과 까닭이 있으면 맞아요.","scoring_points":["나에게 멋진 날을 썼는가","까닭을 썼는가","문장이 자연스러운가"]},"explanation":["기분 좋고 행복했던 때를 떠올려요.","까닭을 「~니까」로 이어 써요.","친구의 멋진 날과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
